const inputs = $input.all();
const out = [];
inputs.forEach((item, idx) => {
  const j = item.json || {};
  const hasKTO = j['Nom produit KTO'] && String(j['Nom produit KTO']).trim() !== '';
  const hasVL = j['Nom produit VosLentilles'] && String(j['Nom produit VosLentilles']).trim() !== '';
  const hasML = j['Nom produit MesLentilles'] && String(j['Nom produit MesLentilles']).trim() !== '';
  const hasLM = j['Nom produit LentillesMaroc'] && String(j['Nom produit LentillesMaroc']).trim() !== '';
  if (!hasLM && (hasKTO || hasVL || hasML)) {
    out.push({ json: { rowNumber: idx + 2 } });
  }
});
out.sort((a, b) => b.json.rowNumber - a.json.rowNumber);
return out;

const f = ($input.first().json.files) || [];
if (!f.length) return [{ json: { rien: true, message: 'Aucun fichier de test restant sur le Drive.' } }];
return f.map(function (x) { return { json: { id: x.id, name: x.name, mimeType: x.mimeType } }; });

const cibles = $('Lister').all().map(function (i) { return i.json; }).filter(function (x) { return x.id; });
const res = $input.all().map(function (i) { return i.json; });
const echecs = res.filter(function (r) { return r && (r.error || r.message); });
return [{ json: {
  fichiersTrouves: cibles.length,
  supprimes: cibles.length - echecs.length,
  restants: echecs.length,
  noms: cibles.map(function (c) { return c.name; })
} }];

const H = this.helpers;
const UA='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36';
const BASE='https://www.lentillesmaroc.ma/wp-json/wc/store/v1';
async function getJson(u,h){return await H.httpRequest({method:'GET',url:u,json:true,returnFullResponse:true,headers:Object.assign({'User-Agent':UA,'Accept':'application/json'},h||{})});}
const r={};
try{
  const vr = await getJson(BASE+'/products?type=variation&parent=526&per_page=30');
  const vars = Array.isArray(vr.body)?vr.body:[];
  r.varCount=vars.length;
  r.varSample = vars.slice(0,4).map(v=>({id:v.id, name:v.name, stock:v.is_in_stock, purchasable:v.is_purchasable, attributes:v.attributes, hasOptions:v.has_options}));
  // parent attributes definition
  const par = await getJson(BASE+'/products/526');
  const pp=par.body||{};
  r.parentAttributes = pp.attributes;
  // cart + try add first variation, capture error body
  const cart0=await getJson(BASE+'/cart'); const hh=cart0.headers||{};
  const addH={'User-Agent':UA,'Accept':'application/json','Content-Type':'application/json'};
  if(hh['nonce']) addH['Nonce']=String(hh['nonce']); if(hh['cart-token']) addH['Cart-Token']=String(hh['cart-token']);
  const v0=vars[0];
  if(v0){
    const vb=(v0.attributes||[]).map(a=>({attribute:a.name,value:a.value}));
    r.tryId=v0.id; r.tryVariation=vb;
    try{
      const add=await H.httpRequest({method:'POST',url:BASE+'/cart/add-item',json:true,body:{id:v0.id,quantity:1,variation:vb},headers:addH,returnFullResponse:true});
      const cart=add.body||{}; const items=cart.items||[];
      r.status=add.statusCode; r.items=items.map(it=>({name:it.name,id:it.id}));
    }catch(e){
      r.errMsg=String((e&&e.message)||'').slice(0,120);
      try{ r.errBody = e && e.response ? JSON.stringify(e.response.body||e.response.data).slice(0,400) : null; }catch(_){}
      if(!r.errBody){ try{ r.errDump = JSON.stringify(e, Object.getOwnPropertyNames(e)).slice(0,500); }catch(_){} }
    }
  }
}catch(e){ r.error=String((e&&e.message)||e).slice(0,300); }
return [{json:r}];

const inputs = $input.all();
const out = [];
for (const item of inputs) {
  const j = item.json || {};
  const hasLM = j['Nom produit LentillesMaroc'] && String(j['Nom produit LentillesMaroc']).trim() !== '';
  if (hasLM) {
    out.push({ json: {
      'ID EyeNeedOptic': j['ID EyeNeedOptic'] || '',
      'Nom produit EyeNeedOptic': j['Nom produit EyeNeedOptic'] || '',
      'URL EyeNeedOptic': j['URL EyeNeedOptic'] || '',
      'Nom produit LentillesMaroc': j['Nom produit LentillesMaroc'] || '',
      'URL LentillesMaroc': j['URL LentillesMaroc'] || '',
      'Actif': j['Actif'] || '',
      'Match validé': j['Match validé'] || '',
      'Type de match': j['Type de match'] || '',
      'Notes': j['Notes'] || ''
    }});
  }
}
return out;

const rows = $('Keep Only LM Rows').all().map(i => i.json);
const header = { json: {
  'ID EyeNeedOptic': 'ID EyeNeedOptic',
  'Nom produit EyeNeedOptic': 'Nom produit EyeNeedOptic',
  'URL EyeNeedOptic': 'URL EyeNeedOptic',
  'Nom produit LentillesMaroc': 'Nom produit LentillesMaroc',
  'URL LentillesMaroc': 'URL LentillesMaroc',
  'Actif': 'Actif',
  'Match validé': 'Match validé',
  'Type de match': 'Type de match',
  'Notes': 'Notes'
}};
return [header, ...rows.map(r => ({ json: r }))];

const H=this.helpers;
const UA='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36';
const r={};
async function g(u){return await H.httpRequest({method:'GET',url:u,json:true,headers:{'User-Agent':UA,'Accept':'application/json'}});}
try{
  // find bella-elite in the list
  let found=null, pagesChecked=0;
  for(let page=1;page<=8;page++){
    const res=await g('https://www.lentillesmaroc.ma/wp-json/wc/store/products?per_page=100&page='+page);
    const arr=Array.isArray(res)?res:(res&&res.products?res.products:[]);
    pagesChecked++;
    if(!arr.length) break;
    for(const p of arr){ if(String(p.permalink||'').includes('bella-elite-collection')){ found=p; break; } }
    if(found) break;
    if(arr.length<100) break;
  }
  r.pagesChecked=pagesChecked;
  if(found){
    r.id=found.id; r.permalink=found.permalink; r.type=found.type;
    r.hasShortDesc=('short_description' in found);
    r.shortDescLen=(found.short_description||'').length;
    r.shortDescSnippet=String(found.short_description||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').slice(0,220);
    r.keys=Object.keys(found);
  } else { r.note='bella-elite not found in list'; }
  // compare with single endpoint
  const one=await g('https://www.lentillesmaroc.ma/wp-json/wc/store/products/526');
  const o=one||{};
  r.singleShortDescLen=(o.short_description||'').length;
  r.singleSnippet=String(o.short_description||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').slice(0,220);
}catch(e){ r.error=String((e&&e.message)||e).slice(0,300); }
return [{json:r}];

return items.map(item => {
  const o = item.json;
  const billing = o.billing || {};
  const shipping = o.shipping || {};
  const lines = Array.isArray(o.line_items) ? o.line_items : [];
  const produits = lines.map(l => `${l.name || ''} x ${l.quantity || 1}`).join(' · ');
  const nom = `${shipping.first_name || billing.first_name || ''} ${shipping.last_name || billing.last_name || ''}`.trim();
  const adresse = [shipping.address_1 || billing.address_1 || '', shipping.address_2 || billing.address_2 || ''].filter(Boolean).join(' ');
  return {
    json: {
      DATE: o.date_created_gmt || o.date_created || '',
      ID: String(o.id || o.number || '').trim(),
      NOM: nom,
      TEL: shipping.phone || billing.phone || '',
      ADRESSE: adresse,
      VILLE: shipping.city || billing.city || '',
      PRODUITS: produits,
      PRIX: o.total || '',
      STATUT: o.status || '',
      PAYMENT_METHOD: o.payment_method_title || o.payment_method || '',
      SOURCE: o.created_via || 'woocommerce',
      CHECKED_AT: new Date().toISOString()
    }
  };
});

const wooItems = $('Filter New Orders Since Last Check').all().map(i => i.json);
const egrow1 = $('Read EGROW Feuille 1').all().map(i => i.json);

const egrowIds = new Set(egrow1
  .map(r => String(r.ID || r.id || '').trim())
  .filter(Boolean));

const staticData = $getWorkflowStaticData('global');
const lastCheckedIdBefore = wooItems[0]?.LAST_CHECKED_ID_BEFORE_RUN || Number(staticData.lastCheckedWooOrderId || 0);
const securityDelayMinutes = wooItems[0]?.SECURITY_DELAY_MINUTES || 5;
const maxCheckedId = Math.max(0, ...wooItems.map(o => Number(o.ID || 0)));

const missingOrders = [];
const seen = new Set();
for (const order of wooItems) {
  const id = String(order.ID || '').trim();
  if (!id || seen.has(id)) continue;
  seen.add(id);
  if (!egrowIds.has(id)) {
    missingOrders.push({
      ...order,
      REMARQUE: 'Commande WooCommerce non trouvée dans EGROW Feuille 1 au moment du contrôle'
    });
  }
}

if (maxCheckedId > 0) {
  staticData.lastCheckedWooOrderId = maxCheckedId;
  staticData.lastCheckedAt = new Date().toISOString();
}

const status = wooItems.length === 0 ? 'OK - Aucune nouvelle commande à vérifier' : (missingOrders.length > 0 ? 'ALERTE - Commandes manquantes' : 'OK - Aucune commande manquante');
const missingIds = missingOrders.map(o => o.ID).join(', ');

return [{
  json: {
    DATE_CHECK: new Date().toISOString(),
    LAST_CHECKED_ID_BEFORE: lastCheckedIdBefore,
    LAST_CHECKED_ID_AFTER: staticData.lastCheckedWooOrderId || lastCheckedIdBefore,
    COMMANDES_VERIFIEES: wooItems.length,
    COMMANDES_MANQUANTES: missingOrders.length,
    MISSING_IDS: missingIds,
    SECURITY_DELAY_MINUTES: securityDelayMinutes,
    STATUS: status,
    REMARQUE: wooItems.length === 0 ? 'Aucune commande WooCommerce plus ancienne que le délai de sécurité et supérieure au dernier ID vérifié.' : '',
    LAST_CHECKED_AT: staticData.lastCheckedAt || null,
    missingOrders
  }
}];

const staticData = $getWorkflowStaticData('global');
const lastCheckedId = Number(staticData.lastCheckedWooOrderId || 0);
const safetyDelayMinutes = 5;
const cutoffTime = Date.now() - safetyDelayMinutes * 60 * 1000;

const newOrders = items
  .map(item => item.json)
  .filter(order => {
    const id = Number(order.ID || 0);
    const createdAt = new Date(order.DATE).getTime();
    const isOldEnough = Number.isFinite(createdAt) ? createdAt <= cutoffTime : true;
    return id > lastCheckedId && isOldEnough;
  })
  .sort((a, b) => Number(a.ID) - Number(b.ID));

return newOrders.map(order => ({
  json: {
    ...order,
    LAST_CHECKED_ID_BEFORE_RUN: lastCheckedId,
    SECURITY_DELAY_MINUTES: safetyDelayMinutes
  }
}));

const summary = $('Compare WooCommerce vs EGROW').first().json || {};
const missingOrders = Array.isArray(summary.missingOrders) ? summary.missingOrders : [];

return missingOrders.map(order => ({
  json: {
    ...order,
    LAST_CHECKED_ID_AFTER_RUN: summary.LAST_CHECKED_ID_AFTER,
    LAST_CHECKED_AT: summary.LAST_CHECKED_AT,
    CHECKED_ORDERS_COUNT: summary.COMMANDES_VERIFIEES,
    MISSING_ORDERS_COUNT: summary.COMMANDES_MANQUANTES
  }
}));

const summary = $('Compare WooCommerce vs EGROW').first().json || {};
const missingOrders = Array.isArray(summary.missingOrders) ? summary.missingOrders : [];
const sheetUrl = 'https://docs.google.com/spreadsheets/d/1lu8-5t2PYXjouIjs3jWGUAnDnhU4-yafne41iIWzH_4/edit';
const hasMissing = missingOrders.length > 0;

const checkedCount = Number(summary.COMMANDES_VERIFIEES || 0);
const lastBefore = summary.LAST_CHECKED_ID_BEFORE ?? '';
const lastAfter = summary.LAST_CHECKED_ID_AFTER ?? '';
const status = summary.STATUS || (hasMissing ? 'ALERTE - Commandes manquantes' : 'OK - Aucune commande manquante');

let detailsHtml = '';
if (hasMissing) {
  const lines = missingOrders
    .map(o => `#${o.ID} - ${o.NOM || ''} - ${o.VILLE || ''} - ${o.PRIX || ''} Dhs`)
    .join('<br>');
  detailsHtml = `<p>Commande(s) absente(s) de EGROW : <strong>${missingOrders.length}</strong></p><p>${lines}</p><p>Voir l’onglet <strong>Commandes manquantes EGROW</strong> dans le Google Sheets WooCommerce.</p>`;
} else {
  detailsHtml = `<p>Commande(s) absente(s) de EGROW : <strong>0</strong></p><p>Aucune commande manquante détectée lors de ce contrôle.</p>`;
}

return [{
  json: {
    sendTo: 'dreamjobma@gmail.com',
    subject: hasMissing
      ? `Alerte EGROW - ${missingOrders.length} commande(s) manquante(s)`
      : `Contrôle EGROW OK - ${checkedCount} commande(s) vérifiée(s)`,
    message: `<p>Bonjour,</p><p>Résultat du contrôle quotidien WooCommerce vs EGROW : <strong>${status}</strong></p><p>Commande(s) WooCommerce vérifiée(s) : <strong>${checkedCount}</strong></p><p>Dernier ID avant contrôle : <strong>${lastBefore}</strong><br>Dernier ID après contrôle : <strong>${lastAfter}</strong></p>${detailsHtml}<p>Google Sheet WooCommerce : ${sheetUrl}</p>`
  }
}];

const s = $('Compare WooCommerce vs EGROW').first().json;
return [{
  json: {
    DATE_CHECK: s.DATE_CHECK,
    LAST_CHECKED_ID_BEFORE: s.LAST_CHECKED_ID_BEFORE,
    LAST_CHECKED_ID_AFTER: s.LAST_CHECKED_ID_AFTER,
    COMMANDES_VERIFIEES: s.COMMANDES_VERIFIEES,
    COMMANDES_MANQUANTES: s.COMMANDES_MANQUANTES,
    MISSING_IDS: s.MISSING_IDS,
    SECURITY_DELAY_MINUTES: s.SECURITY_DELAY_MINUTES,
    STATUS: s.STATUS,
    REMARQUE: s.REMARQUE,
    LAST_CHECKED_AT: s.LAST_CHECKED_AT
  }
}];

