// Un export reussi commence par la signature %PDF. On verifie aussi
// qu'il contient des polices : sans elles, ce serait une image et il
// faudrait passer par la vision, ce qui est justement notre branche.
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const tete = buffer.slice(0, 5).toString('latin1');
const texte = buffer.toString('latin1');

return [{ json: {
  octets: buffer.length,
  signature: tete,
  estUnPdf: tete === '%PDF-',
  nbPolices: (texte.match(/\/Font/g) || []).length,
  idDoc: $('Convertir en Google Doc').first().json.id,
  idSource: $('Deposer sur Drive').first().json.id
} }];

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
return [{ json: { body: {
  model: 'gpt-4.1-mini',
  temperature: 0,
  text: { format: { type: 'json_object' } },
  input: [{ role: 'user', content: [
    { type: 'input_file', filename: 'cv.pdf', file_data: 'data:application/pdf;base64,' + buffer.toString('base64') },
    { type: 'input_text', text: 'Ce document est un CV. Reponds UNIQUEMENT en JSON valide : {"lisible": <true|false>, "nom": "", "postes": [{"intitule": "", "employeur": "", "periode": ""}], "resume": "2 phrases"}' }
  ] }]
} } }];

const r = $input.first().json;
let texte = r.output_text || '';
if (!texte && Array.isArray(r.output)) {
  for (const o of r.output) {
    if (Array.isArray(o.content)) {
      for (const c of o.content) { if (typeof c.text === 'string') texte += c.text; }
    }
  }
}
let lecture = null;
const i = texte.indexOf('{'), j = texte.lastIndexOf('}');
if (i !== -1 && j !== -1) { try { lecture = JSON.parse(texte.slice(i, j + 1)); } catch (e) {} }

// On lit les noeuds Drive de notre propre branche : « Verifier le PDF »
// est sur une branche parallele que n8n n'a pas forcement deja executee.
const idDoc = $('Convertir en Google Doc').first().json.id;
const idSource = $('Deposer sur Drive').first().json.id;

// Les fichiers deposes sur le Drive ne servent qu'a la conversion. On y
// ajoute ceux qu'ont laisses les essais precedents, pour ne rien laisser
// trainer dans le Drive.
const ORPHELINS = [
  '1PmZAb4iXXDL24Xf2KeddmZB-RQIjJ0WOJsIKG2qxDAo',
  '1GBHa99nvd6zz4oHOLkylv58oCIGtn4HZ',
  '1z607TZtD-0FmHZj23CJR5xiu2ZWDOAjUJAFeklwpxGw',
  '1NoxxOl8Mab7pWrgE2yrGwrtInD2d0ttm'
];

const out = [{ json: { etape: 'resultat', tokens: r.usage || null, lecture: lecture } }];
for (const id of [idDoc, idSource].concat(ORPHELINS)) {
  if (id) out.push({ json: { etape: 'nettoyage', id: id } });
}
return out;

const items = $input.all();
const match = items.find(function(it){ return (it.json.sheet_url || '').includes('18A9WrkhuyAmOEmR35e_3Mf2OHA-fPsRhcFBMbtIewmY'); });
if (!match) { throw new Error('Vendeuse job row not found in Jobs tab'); }
return [{ json: { job_title: match.json.job_title, job_description: match.json.job_description, sheet_url: match.json.sheet_url } }];

const items = $input.all();
const job = $('Get Vendeuse Job').first().json;

function normalizeHeader(s){
  return (s || '').toString().toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]/g, '');
}
function findKey(keys, includes, excludes){
  excludes = excludes || [];
  for (const k of keys){
    const nk = normalizeHeader(k);
    if (excludes.some(function(e){ return nk.includes(e); })) continue;
    if (includes.some(function(inc){ return nk.includes(inc); })) return k;
  }
  return null;
}

const results = [];
for (const item of items){
  const json = item.json;
  const keys = Object.keys(json);
  const kLastName = findKey(keys, ['nom'], ['prenom']);
  const kFirstName = findKey(keys, ['prenom']);
  const kFullName = findKey(keys, ['nomcomplet', 'fullname', 'candidat']);
  const kEmail = findKey(keys, ['mail']);
  const kPhone = findKey(keys, ['telephone', 'gsm', 'phone']);
  const kCity = findKey(keys, ['ville', 'residence', 'city']);
  const kDesiredPos = findKey(keys, ['postesouhaite', 'poste', 'position']);
  const kExperience = findKey(keys, ['experience']);
  const kEducation = findKey(keys, ['etudes', 'diplome', 'niveau']);
  const kCv = findKey(keys, ['cv', 'resume', 'curriculum']);

  const cvLink = kCv ? String(json[kCv] || '').trim() : '';
  if (!cvLink) continue;

  let name = kFullName ? String(json[kFullName] || '').trim() : '';
  if (!name){
    const first = kFirstName ? String(json[kFirstName] || '').trim() : '';
    const last = kLastName ? String(json[kLastName] || '').trim() : '';
    name = [first, last].filter(Boolean).join(' ');
  }

  results.push({
    json: {
      jobTitle: job.job_title || 'Offre sans titre',
      jobDescription: job.job_description || '',
      name: name || 'Sans nom',
      email: kEmail ? String(json[kEmail] || '').trim() : '',
      phone: kPhone ? String(json[kPhone] || '').trim() : '',
      city: kCity ? String(json[kCity] || '').trim() : '',
      desiredPosition: kDesiredPos ? String(json[kDesiredPos] || '').trim() : '',
      experienceYears: kExperience ? String(json[kExperience] || '').trim() : '',
      educationLevel: kEducation ? String(json[kEducation] || '').trim() : '',
      cvLink: cvLink
    }
  });
}
return results;

