const json = $input.item.json;
const candidate = $('Normalize Candidates').item.json;

function extractRawText(json){
  if (typeof json.aiRawText === 'string') return json.aiRawText;
  if (typeof json.output === 'string') return json.output;
  if (typeof json.content === 'string') return json.content;
  if (typeof json.text === 'string') return json.text;
  if (json.message && typeof json.message.content === 'string') return json.message.content;
  if (Array.isArray(json.content) && json.content[0] && json.content[0].text) return json.content[0].text;
  return JSON.stringify(json);
}

function parseJsonLoose(text){
  let c = (text || '').trim();
  c = c.split('```json').join('');
  c = c.split('```').join('');
  c = c.trim();
  const start = c.indexOf('{');
  const end = c.lastIndexOf('}');
  if (start === -1 || end === -1) return { error: 'Réponse IA illisible.' };
  try { return JSON.parse(c.slice(start, end + 1)); }
  catch (e) { return { error: 'Réponse IA illisible.' }; }
}

const raw = extractRawText(json);
const parsed = parseJsonLoose(raw);

return {
  json: {
    job_title: candidate.jobTitle,
    candidate_name: candidate.name,
    email: candidate.email,
    phone: candidate.phone,
    city: candidate.city,
    desired_position: candidate.desiredPosition,
    experience_years: candidate.experienceYears,
    education_level: candidate.educationLevel,
    cv_link: candidate.cvLink,
    score: parsed.error ? '' : parsed.score,
    recommendation: parsed.error ? parsed.error : (parsed.recommendation || ''),
    strengths: parsed.error ? '' : (Array.isArray(parsed.strengths) ? parsed.strengths.join(' | ') : ''),
    gaps: parsed.error ? '' : (Array.isArray(parsed.gaps) ? parsed.gaps.join(' | ') : ''),
    summary: parsed.error ? '' : (parsed.summary || ''),
    status: 'Nouveau',
    analyzed_at: new Date().toISOString()
  }
};

