// catalogue Woo : URL exacte -> slug exact -> tokens du slug (match unique) -> nom.
const SLUG_FILLER = new Set(['produit','produits','lentille','lentilles','de','des','la','le','les','ml','couleur','couleurs']);
function slugTokens07(u){
  const parts = s(u).replace(/[?#].*$/,'').split('/').filter(Boolean);
  const slug = (parts[parts.length-1]||'').toLowerCase();
  return slug.replace(/[^a-z0-9-]+/g,'-').split('-').filter(Boolean).filter(t=>!/^\d+$/.test(t) && !SLUG_FILLER.has(t));
}
