  if(!p.url) continue;
  const c = slugTokens07(p.url).join(' ');
  if(c && !ownBySlugCore[c]) ownBySlugCore[c] = p;
}
function resolveEnoProduct(u, nm){
  if(u && ownByUrl[u]) return ownByUrl[u];
  const toks = slugTokens07(u);
  const core = toks.join(' ');
  if(core && ownBySlugCore[core]) return ownBySlugCore[core];
  if(toks.length){
    const set = new Set(toks);
    const cands = [];
    for(const c2 in ownBySlugCore){
      const t2 = c2.split(' ');
      const s2 = new Set(t2);
      if(t2.every(t=>set.has(t)) || toks.every(t=>s2.has(t))) cands.push(ownBySlugCore[c2]);
    }
    if(cands.length === 1) return cands[0];
  }
  if(nm && ownByName[key(nm)]) return ownByName[key(nm)];
  return null;
}

