<script>
const RAW = __DATA_PLACEHOLDER__;
const DELTA = __DELTA_PLACEHOLDER__;
const AVALIDER_COUNT = __AVALIDER_COUNT_PLACEHOLDER__;
const COVERAGE_PCT = __COVERAGE_PLACEHOLDER__;
const AVG_GAP_DH = __AVG_GAP_DH_PLACEHOLDER__;
const AVG_GAP_PCT = __AVG_GAP_PCT_PLACEHOLDER__;
const TOTAL_OPPORTUNITY = __TOTAL_OPPORTUNITY_PLACEHOLDER__;
const TOP5 = __TOP5_PLACEHOLDER__;
const HISTORY = __HISTORY_PLACEHOLDER__;
const SITE_LABELS = __SITE_LABELS_PLACEHOLDER__;

const MAD = new Intl.NumberFormat('fr-MA', {maximumFractionDigits:0});
const ALERT_THRESHOLD_PCT = 15;

document.getElementById('titleSites').textContent = SITE_LABELS.length ? SITE_LABELS.join(' / ') : 'concurrents';

function computed(row){
  let winner = 'tie', gap = 0, pct = 0;
  if (row.ep != null && row.cp != null){
    if (row.ep < row.cp){ winner='eno'; gap = row.cp - row.ep; }
    else if (row.cp < row.ep){ winner='comp'; gap = row.ep - row.cp; }
    pct = row.ep ? Math.round((gap/row.ep)*1000)/10 : 0;
  }
  return {...row, winner, gap, pct};
}
const DATA = RAW.map(computed);

// ---- snapshot date + age ----
const snapshotDate = new Date();
document.getElementById('snapshotDate').textContent = snapshotDate.toLocaleDateString('fr-FR', {day:'2-digit', month:'long', year:'numeric'});
function updateAge(){
  const days = Math.floor((Date.now() - snapshotDate.getTime()) / 86400000);
  const el = document.getElementById('snapshotAge');
  if (days <= 0) el.textContent = '(aujourd\'hui)';
  else if (days === 1) el.textContent = '(il y a 1 jour)';
  else el.textContent = '(il y a ' + days + ' jours)';
}
updateAge();

if (AVALIDER_COUNT != null) {
  document.getElementById('btnValidate').textContent = '→ Valider ' + AVALIDER_COUNT + ' produits';
}

// ---- delta badge ----
const deltaEl = document.getElementById('deltaBadge');
if (DELTA > 0) { deltaEl.innerHTML = '<span class="delta up">+' + DELTA + ' vs dernier run</span>'; }
else if (DELTA < 0) { deltaEl.innerHTML = '<span class="delta up" style="background:var(--coral-soft);color:var(--coral);">' + DELTA + ' vs dernier run</span>'; }
else { deltaEl.innerHTML = '<span class="delta flat">stable vs dernier run</span>'; }

// ---- KPIs + lens gauge ----
const nEno = DATA.filter(d=>d.winner==='eno').length;
const nTie = DATA.filter(d=>d.winner==='tie').length;
const nComp  = DATA.filter(d=>d.winner==='comp').length;
const total = DATA.length;

document.getElementById('kpiEno').textContent = nEno;
document.getElementById('kpiTie').textContent = nTie;
document.getElementById('kpiLm').textContent  = nComp;
document.getElementById('pctEno').textContent = total ? Math.round(((nEno+nTie)/total)*100) + '%' : '—';

const R = 86, C = 2*Math.PI*R;
function setArc(el, fraction, offsetFraction){
  el.setAttribute('stroke-dasharray', (fraction*C) + ' ' + C);
  el.setAttribute('stroke-dashoffset', -(offsetFraction*C));
}
if (total) {
  setArc(document.getElementById('arcEno'), nEno/total, 0);
  setArc(document.getElementById('arcTie'), nTie/total, nEno/total);
  setArc(document.getElementById('arcLm'),  nComp/total,  (nEno+nTie)/total);
}

// ---- insight tiles ----
document.getElementById('insCoverage').textContent = (COVERAGE_PCT != null) ? COVERAGE_PCT + '%' : '—';
document.getElementById('insAvgGap').textContent = AVG_GAP_DH ? (MAD.format(AVG_GAP_DH) + ' DH (' + AVG_GAP_PCT + '%)') : '—';
document.getElementById('insOpportunity').textContent = TOTAL_OPPORTUNITY ? (MAD.format(TOTAL_OPPORTUNITY) + ' DH') : '0 DH';

// ---- top 5 opportunities ----
const oppsList = document.getElementById('oppsList');
if (!TOP5.length) {
  oppsList.innerHTML = '<li class="opps-empty">Aucun écart en défaveur d\'EyeNeedOptic actuellement.</li>';
} else {
  oppsList.innerHTML = TOP5.map(o => (
    '<li><a href="'+o.cu+'" target="_blank" rel="noopener">'+o.n+'</a>'
    + '<span class="amt">-'+MAD.format(o.gap)+' DH<span>'+o.pct+'% &middot; '+o.cs+'</span></span></li>'
  )).join('');
}

// ---- sparkline (match_count history) ----
const sparkWrap = document.getElementById('sparkWrap');
if (HISTORY.length >= 2) {
  const vals = HISTORY.map(h=>h.v);
  const min = Math.min(...vals), max = Math.max(...vals);
  const w = 120, h = 28, pad = 2;
  const span = (max - min) || 1;
  const pts = HISTORY.map((pt,i) => {
    const x = pad + (i/(HISTORY.length-1)) * (w - pad*2);
    const y = h - pad - ((pt.v - min)/span) * (h - pad*2);
    return x.toFixed(1)+','+y.toFixed(1);
  }).join(' ');
  sparkWrap.innerHTML = '<svg width="'+w+'" height="'+h+'" viewBox="0 0 '+w+' '+h+'"><polyline points="'+pts+'" fill="none" stroke="#0F968F" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>';
}

// ---- table rendering ----
const tbody = document.getElementById('tbody');
const emptyState = document.getElementById('emptyState');
let sortKey = 'gap', sortDir = -1, activeFilter = 'all', query = '', sortMode = 'dh';

function fmtPrice(v, url, siteLabel){
  if (v == null) return '<span style="color:var(--ink-soft)">—</span>';
  const tag = siteLabel ? '<span class="sitetag">'+siteLabel+'</span>' : '';
  return '<a href="'+url+'" target="_blank" rel="noopener">'+MAD.format(v)+' DH</a>'+tag;
}

function render(){
  let rows = DATA.filter(d=>{
    if (activeFilter!=='all' && d.winner!==activeFilter) return false;
    if (query && !d.n.toLowerCase().includes(query) && !d.cn.toLowerCase().includes(query)) return false;
    return true;
  });

  const effectiveKey = (sortKey === 'gap' && sortMode === 'pct') ? 'pct' : sortKey;

  rows.sort((a,b)=>{
    let av=a[effectiveKey], bv=b[effectiveKey];
    if (typeof av === 'string') { av = av.toLowerCase(); bv = bv.toLowerCase(); }
    if (av==null) av = -Infinity;
    if (bv==null) bv = -Infinity;
    if (av<bv) return -1*sortDir;
    if (av>bv) return 1*sortDir;
    return 0;
  });

  if (!rows.length){
    tbody.innerHTML='';
    emptyState.style.display='block';
    return;
  }
  emptyState.style.display='none';

  const maxGap = Math.max(...DATA.map(d=> sortMode==='pct' ? d.pct : d.gap), 1);

  tbody.innerHTML = rows.map(d=>{
    const badge = d.winner==='eno' ? '<span class="badge eno">Vous</span>'
                : d.winner==='comp'  ? '<span class="badge comp">'+(d.cs||'Concurrent')+'</span>'
                : '<span class="badge tie">Égalité</span>';
    const isAlert = d.winner==='comp' && d.pct >= ALERT_THRESHOLD_PCT;
    const warnBadge = isAlert ? '<span class="badge warn">&ge; '+ALERT_THRESHOLD_PCT+'%</span>' : '';
    const barColor = d.winner==='eno' ? 'var(--teal)' : d.winner==='comp' ? 'var(--coral)' : 'var(--gold)';
    const barVal = sortMode==='pct' ? d.pct : d.gap;
    const barWidth = barVal ? Math.max(6, Math.round((barVal/maxGap)*100)) : 0;
    return '<tr class="'+(isAlert?'alert':'')+'">'
      + '<td class="prod"><a href="'+d.eu+'" target="_blank" rel="noopener">'+d.n+'</a>'
      +   (d.cn && d.n!==d.cn ? '<span class="sub">≈ '+d.cn+'</span>' : '')
      + '</td>'
      + '<td class="price '+(d.winner==='eno'?'winner-eno':'')+'">'+fmtPrice(d.ep, d.eu)+'</td>'
      + '<td class="price '+(d.winner==='comp'?'winner-comp':'')+'">'+fmtPrice(d.cp, d.cu, d.cs)+'</td>'
      + '<td><div class="gapbar-wrap"><div class="gapbar"><i style="width:'+barWidth+'%;background:'+barColor+';"></i></div>'
      +   '<span class="gap-val">'+(d.gap ? MAD.format(d.gap)+' DH' : '—')
      +     (d.gap ? '<span class="gap-pct">'+d.pct+'%</span>' : '')+'</span></div></td>'
      + '<td>'+badge+warnBadge+'</td>'
      + '</tr>';
  }).join('');
}

document.querySelectorAll('thead th').forEach(th=>{
  th.addEventListener('click', ()=>{
    const key = th.dataset.key;
    if (sortKey===key) sortDir *= -1; else { sortKey=key; sortDir = key==='n'?1:-1; }
    document.querySelectorAll('thead th').forEach(t=>t.classList.remove('sorted'));
    th.classList.add('sorted');
    render();
  });
});

document.querySelectorAll('.filters .chip').forEach(chip=>{
  chip.addEventListener('click', ()=>{
    document.querySelectorAll('.filters .chip').forEach(c=>c.classList.remove('active'));
    chip.classList.add('active');
    activeFilter = chip.dataset.filter;
    render();
  });
});

document.querySelectorAll('.sortrow .chip').forEach(chip=>{
  chip.addEventListener('click', ()=>{
    document.querySelectorAll('.sortrow .chip').forEach(c=>c.classList.remove('active'));
    chip.classList.add('active');
    sortMode = chip.dataset.sortmode;
    render();
  });
});

document.getElementById('searchBox').addEventListener('input', (e)=>{
  query = e.target.value.trim().toLowerCase();
  render();
});

document.getElementById('btnPrint').addEventListener('click', ()=> window.print());

document.getElementById('btnExport').addEventListener('click', ()=>{
  const header = ['Produit EyeNeedOptic','Prix EyeNeedOptic','Meilleur concurrent','Prix concurrent','Ecart (DH)','Ecart (%)','Moins cher'];
  const lines = [header.join(';')];
  DATA.forEach(d=>{
    const winnerLabel = d.winner==='eno' ? 'EyeNeedOptic' : d.winner==='comp' ? (d.cs||'Concurrent') : 'Egalite';
    lines.push([
      '"'+d.n.replace(/"/g,'""')+'"',
      d.ep ?? '',
      '"'+(d.cn||'').replace(/"/g,'""')+'"',
      d.cp ?? '',
      d.gap || 0,
      d.pct || 0,
      winnerLabel
    ].join(';'));
  });
  const blob = new Blob(['\ufeff'+lines.join('\n')], {type:'text/csv;charset=utf-8;'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'comparaison-prix-' + new Date().toISOString().slice(0,10) + '.csv';
  a.click();
  URL.revokeObjectURL(url);
});

render();
</script>
</body>
</html>
";
const html = template
  .replace('__DATA_PLACEHOLDER__', JSON.stringify(rows))
  .replace('__DELTA_PLACEHOLDER__', String(delta))
  .replace('__AVALIDER_COUNT_PLACEHOLDER__', toValidateCount == null ? 'null' : String(toValidateCount))
  .replace('__AVALIDER_URL__', AVALIDER_URL)
  .replace('__COUNT_PLACEHOLDER__', String(rows.length))
  .replace('__SITES_COUNT_PLACEHOLDER__', String(totalSitesCount))
  .replace('__SITE_LABELS_PLACEHOLDER__', JSON.stringify(siteLabels))
  .replace('__COVERAGE_PLACEHOLDER__', coveragePct == null ? 'null' : String(coveragePct))
  .replace('__AVG_GAP_DH_PLACEHOLDER__', String(avgGapDh))
  .replace('__AVG_GAP_PCT_PLACEHOLDER__', String(avgGapPct))
  .replace('__TOTAL_OPPORTUNITY_PLACEHOLDER__', String(totalOpportunityDh))
  .replace('__TOP5_PLACEHOLDER__', JSON.stringify(top5))
  .replace('__HISTORY_PLACEHOLDER__', JSON.stringify(historySeries));

const binary = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf-8'), 'dashboard.html', 'text/html');
return [{ json: { rowCount: rows.length, previousCount, delta, debugPrev, avgGapDh, avgGapPct, coveragePct, totalOpportunityDh, outOfStockHidden, nEno, nTie, nLm: nComp, toValidateCount, ownTotal }, binary: { data: binary } }];

// Détection cadeau LM : motif « solution/produit … offert(e) » dans le
// short_description de l'API Store (évite les faux positifs « livraison
// gratuite »). Refetch LM (isolé, non bloquant) -> gift/gift_text sur l'entrée
// LM de all_sites (jsonb, aucune migration). Badge dashboard.
const H = this.helpers;
const giftByUrl = new Map();
try {
  const A = /(?:une |la |le |un |du |des )?(?:solution|produit|flacon|gel|liquide)[^.!\n]{0,70}\boffert(?:e|es)?\b[^.!\n]{0,25}/i;
  const B = /\boffert(?:e|es)?\b[^.!\n]{0,70}(?:solution|produit|flacon|gel|liquide|entretien)/i;
  const UA='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36';
  for (let page=1; page<=8; page++){
    let products=[];
    try {
      const res = await H.httpRequest({ method:'GET', url:'https://www.lentillesmaroc.ma/wp-json/wc/store/products?per_page=100&page='+page, json:true, timeout:15000, headers:{ 'User-Agent':UA, 'Accept':'application/json' } });
      products = Array.isArray(res)?res:(res&&Array.isArray(res.products)?res.products:[]);
    } catch(e){ break; }
    if (!products.length) break;
    for (const p of products){
      const sd = String(p.short_description||'').replace(/<[^>]+>/g,' ').replace(/&[a-z#0-9]+;/gi,' ').replace(/\s+/g,' ').trim();
      const m = sd.match(A) || sd.match(B);
      if (m){
        const url = String(p.permalink||'').replace(/[?#].*$/,'').replace(/\/$/,'').toLowerCase();
        if(url) giftByUrl.set(url, m[0].replace(/^[\s\-–—:]+/,'').replace(/\s+/g,' ').trim().slice(0,150));
      }
    }
    if (products.length < 100) break;
  }
} catch(e){}
function giftFor(u){ if(!u) return null; return giftByUrl.get(String(u).replace(/[?#].*$/,'').replace(/\/$/,'').toLowerCase())||null; }

let comparison = [];
try { comparison = $('07C - Fix Best Price Logic').first().json.comparison || []; } catch(e) {}
let toValidateRows = [];
try { toValidateRows = $('07C - Fix Best Price Logic').first().json.toValidateRows || []; } catch(e) {}
let outOfStockRows = [];
try { outOfStockRows = $('07C - Fix Best Price Logic').first().json.outOfStock || []; } catch(e) {}
let scopedCompetitors = [];
try { scopedCompetitors = $('07C - Fix Best Price Logic').first().json.scopedCompetitors || []; } catch(e) {}
const toValidateCount = toValidateRows.length;
let ownTotal = null;
let outOfStockHidden = null;
try {
  const dbg = $('07C - Fix Best Price Logic').first().json.debugManualMapping || {};
  ownTotal = (typeof dbg.ownProducts === 'number') ? dbg.ownProducts : null;
  outOfStockHidden = (typeof dbg.skippedOutOfStock === 'number') ? dbg.skippedOutOfStock : 0;
} catch(e) {}

const siteLabelsSet = new Set();
for (const r of comparison) {
  for (const k of Object.keys(r)) {
    const m = k.match(/^Prix (.+)$/);
    if (m && m[1] !== 'EyeNeedOptic') siteLabelsSet.add(m[1]);
  }
}
const siteLabels = Array.from(siteLabelsSet).sort();

const comparisons = [];
let nEno = 0, nTie = 0, nComp = 0, sumGapOpp = 0, sumPctOpp = 0, cntOpp = 0;

for (const r of comparison) {
  const ep = r['Prix EyeNeedOptic'];
  const eu = r['URL EyeNeedOptic'] || '';
  const en = r['Nom produit EyeNeedOptic'] || '';
  if (!eu) continue;
  const competitors = [];
  for (const site of siteLabels) {
    const p = r['Prix ' + site];
    if (typeof p === 'number') {
      const cu = r['URL ' + site] || '';
      const gt = giftFor(cu);
      competitors.push({ site, price: p, url: cu, name: r['Nom produit ' + site] || '', stock: r['Stock ' + site] || 'unknown', gift: !!gt, gift_text: gt });
    }
  }
  let best = null;
  for (const c of competitors) {
    if (best === null || c.price < best.price) best = c;
  }
  const epNum = (typeof ep === 'number') ? ep : null;
  const cp = best ? best.price : null;
  let winner = 'unknown', gap = 0, gapPct = 0;
  if (epNum != null && cp != null) {
    if (epNum < cp) { winner = 'eno'; nEno++; }
    else if (cp < epNum) {
      winner = 'comp'; nComp++;
      gap = Math.round((epNum - cp) * 100) / 100;
      gapPct = epNum ? Math.round((gap / epNum) * 1000) / 10 : 0;
      sumGapOpp += gap; sumPctOpp += gapPct; cntOpp++;
    } else { winner = 'tie'; nTie++; }
  }
  comparisons.push({
    product_key: eu,
    eno_name: en,
    eno_url: eu,
    eno_price: epNum,
    eno_stock: r['Stock EyeNeedOptic'] || 'unknown',
    best_site: best ? best.site : null,
    best_name: best ? best.name : null,
    best_url: best ? best.url : null,
    best_price: cp,
    best_stock: best ? (best.stock || 'unknown') : null,
    all_sites: competitors,
    winner,
    gap,
    gap_pct: gapPct,
  });
}

const avgGapDh = cntOpp ? Math.round((sumGapOpp / cntOpp) * 100) / 100 : 0;
const avgGapPct = cntOpp ? Math.round((sumPctOpp / cntOpp) * 10) / 10 : 0;
const totalOpportunityDh = Math.round(sumGapOpp * 100) / 100;
const coveragePct = ownTotal ? Math.round((comparisons.length / ownTotal) * 1000) / 10 : null;

// Santé du scraping calculée sur la sortie de 04F (prix concurrents), qui porte
// le stock RÉEL parsé de chaque concurrent — KTO compris (schema.org
// availability), LM (API Store), et les fiches KTO servies par le cache.
// L'ancienne source (04D) était EN AMONT du parsing stock, d'où KTO
// systématiquement « 100% indéterminé » alors que le stock est bien connu.
let scrapingHealth = [];
try {
  const rows04f = $('04F - Extract Competitor Prices').all().map(i => i.json || {});
  const bySite = {};
  for (const r of rows04f) {
    if (!r || r.role !== 'competitor') continue;
    const sid = r.siteName || r.siteId;
    if (!sid) continue;
    if (!bySite[sid]) bySite[sid] = { total: 0, unknown: 0 };
    bySite[sid].total++;
    const st = r.stockStatus;
    if (st !== 'instock' && st !== 'outofstock') bySite[sid].unknown++;
  }
  scrapingHealth = Object.entries(bySite).map(([site, v]) => ({
    site,
    total: v.total,
    unknown_pct: v.total ? Math.round((v.unknown / v.total) * 1000) / 10 : 0,
  }));
} catch (e) {}

const stats = {
  match_count: comparisons.length,
  avg_gap_dh: avgGapDh,
  avg_gap_pct: avgGapPct,
  coverage_pct: coveragePct,
  total_opportunity_dh: totalOpportunityDh,
  out_of_stock_hidden: outOfStockHidden,
  n_eno: nEno,
  n_tie: nTie,
  n_comp: nComp,
  to_validate_count: toValidateCount,
  own_total: ownTotal,
  site_labels: siteLabels,
  scraping_health: scrapingHealth,
};

const pending_matches = toValidateRows.map(r => ({
  type: r['Type'] || '',
  eno_name: r['Nom produit EyeNeedOptic'] || null,
  eno_price: (typeof r['Prix EyeNeedOptic'] === 'number') ? r['Prix EyeNeedOptic'] : null,
  eno_url: r['URL EyeNeedOptic'] || null,
  suggested_site: r['Site suggéré'] || null,
  suggested_name: r['Nom produit suggéré'] || null,
  suggested_price: (typeof r['Prix suggéré'] === 'number') ? r['Prix suggéré'] : null,
  suggested_url: r['URL suggérée'] || null,
  notes: r['Notes'] || null,
}));

const price_history = comparisons.map(c => ({
  product_key: c.product_key,
  eno_price: c.eno_price,
  best_price: c.best_price,
  best_site: c.best_site,
  gap: c.gap,
  gap_pct: c.gap_pct,
}));

const out_of_stock_products = outOfStockRows.map(r => ({
  eno_name: r['Nom produit EyeNeedOptic'] || null,
  eno_price: (typeof r['Prix EyeNeedOptic'] === 'number') ? r['Prix EyeNeedOptic'] : null,
  eno_url: r['URL EyeNeedOptic'] || null,
  sites: r['Sites en rupture'] || null,
}));

const competitor_catalog = scopedCompetitors.map(c => ({
  site: c.site || null,
  url: c.url || null,
  name: c.name || null,
  price: (typeof c.price === 'number') ? c.price : null,
  category: c.category || null,
})).filter(c => c.url);

return [{ json: { comparisons, stats, pending_matches, price_history, out_of_stock_products, competitor_catalog } }];

let stats = {};
let comparisons = [];
try {
  const j = $('22 - Build Supabase Payload').first().json;
  stats = j.stats || {};
  comparisons = j.comparisons || [];
} catch(e) {}

let newProducts = [];
let priceDrops = [];
let newlyOos = [];
let scrapeAlerts = [];
let giftAdded = [];
let giftRemoved = [];
