// Rattrapage ponctuel. Les candidats de l offre Restauration ont leur CV
// depose dans le bucket, mais aucune fiche ne porte le chemin : le scanner
// lisait le noeud de depot a travers une branche parallele et l appariement
// echouait en silence (corrige en v10.7). Le chemin se recalcule depuis le
// lien du CV, exactement comme l URL de depot.
//
// Rien n est ecrit sans preuve : seules les fiches dont le fichier est
// present ET non vide dans le bucket sont renseignees. Un chemin qui pointe
// vers rien serait pire que pas de chemin, car le dashboard signerait une
// URL morte au lieu de retomber sur le lien Fillout.
//
// Idempotent : les fiches qui portent deja un chemin sont ignorees, donc
// relancer cet outil ne refait rien.
const OFFRE = '80f6f400-f57f-4b41-9045-19d5a2ed257d';

function dec(s) { try { return decodeURIComponent(s); } catch (e) { return s; } }
function nomFichier(lien) { return String(lien || '').split('?')[0].split('/').pop() || 'cv'; }

const tailleParNom = {};
$input.all().map(function (i) { return i.json; }).forEach(function (o) {
  if (o && typeof o.name === 'string' && o.name) {
    tailleParNom[dec(o.name)] = o.metadata && typeof o.metadata.size === 'number' ? o.metadata.size : 0;
  }
});

const cands = $('Lire les candidats').all().map(function (i) { return i.json; })
  .filter(function (c) { return c.job_id === OFFRE && !c.archived_at && !c.cv_storage_path; });

const aEcrire = [];
const ignores = [];
cands.forEach(function (c) {
  const brut = nomFichier(c.cv_link);
  const taille = tailleParNom[dec(brut)];
  if (!taille) {
    ignores.push({ candidat: c.candidate_name, fichier: dec(brut), raison: taille === undefined ? 'absent du bucket' : 'fichier vide' });
    return;
  }
  aEcrire.push({ json: {
    id: c.id,
    candidat: c.candidate_name,
    cv_storage_path: c.job_id + '/' + encodeURIComponent(brut),
    octets: taille
  } });
});

// Zero item arrete la chaine : aucune ecriture ne part sans cible. Un item
// vide ici produirait un filtre sur un identifiant vide, donc potentiellement
// une mise a jour de toute la table.
console.log('a ecrire : ' + aEcrire.length + ', ignores : ' + ignores.length);
if (ignores.length) console.log(JSON.stringify(ignores));
return aEcrire;

// Le statut « succes » de n8n ne prouve rien : on relit la base et on
