const H = this.helpers;
const UA='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36';
const BASE='https://www.lentillesmaroc.ma/wp-json/wc/store/v1';
const TESTS=[{slug:'bella-elite-collection',expect:'avec cadeau'},{slug:'biofinity-coopervision',expect:'sans cadeau'}];
async function getJson(u,h){return await H.httpRequest({method:'GET',url:u,json:true,returnFullResponse:true,headers:Object.assign({'User-Agent':UA,'Accept':'application/json'},h||{})});}
const out=[];
for(const t of TESTS){
  const r={slug:t.slug,expect:t.expect};
  try{
    const pr=await getJson(BASE+'/products?slug='+encodeURIComponent(t.slug));
    const prod=(Array.isArray(pr.body)?pr.body:[])[0]||null;
    if(!prod){ r.note='not found'; out.push(r); continue; }
    r.slugId=prod.id; r.name=prod.name; r.type=prod.type;
    // Id parent réel : si le slug renvoie une variation, on prend son parent.
    const parentId = (prod.type==='variation' && prod.parent) ? prod.parent : prod.id;
    r.parentId=parentId;
    let addId, variationBody;
    if(prod.type==='simple'){ addId=prod.id; }
    else {
      const vr = await getJson(BASE+'/products?type=variation&parent='+parentId+'&per_page=30');
