const FREE = ['gmail.com','googlemail.com','yahoo.com','yahoo.fr','yahoo.co.uk','hotmail.com','hotmail.fr','outlook.com','outlook.fr','live.fr','live.com','icloud.com','me.com','msn.com','aol.com','gmx.com','gmx.fr','protonmail.com','proton.me','yandex.com','menara.ma','iam.ma','voila.fr','laposte.net','free.fr','orange.fr','sfr.fr','wanadoo.fr','mail.ru','yopmail.com'];
