const EMP = ["publier","diffuser","offre d'emploi","offres d'emploi","nous recherchons","nous recrutons","notre societe","notre entreprise","notre cabinet","tdr","termes de reference","poste a pourvoir","recrute","annonce","nous cherchons","notre client","souhaitons recruter","publication","profil recherche","candidats","offre"];
const CAND = ["mon cv","ci-joint mon cv","je recherche un","je suis a la recherche","a la recherche d'un poste","a la recherche d'une","candidature","je souhaite postuler","je postule","demandeur d'emploi","je suis diplome","jeune diplome","mon profil","opportunite professionnelle","cherche un emploi","je veux travailler","je suis etudiant","mes competences","je me permets de vous contacter"];

function strip(s){
  return (s == null ? '' : String(s)).toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();
}
function titleCase(s){
  const v = (s == null ? '' : String(s)).trim().replace(/\s+/g,' ');
  if (!v) return '';
  return v.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' ');
}
function normPhone(raw){
  let d = (raw == null ? '' : String(raw)).replace(/[^0-9]/g,'');
  if (!d) return '';
  d = d.replace(/^00/,'');
  if (d.indexOf('212') === 0 && d.length >= 11 && d.length <= 13) return '+' + d;
  if (d.charAt(0) === '0' && d.length === 10) return '+212' + d.slice(1);
  if (d.length === 9 && (d.charAt(0) === '6' || d.charAt(0) === '7' || d.charAt(0) === '5')) return '+212' + d;
  if (d.length >= 8 && d.length <= 15) return '+' + d;
  return '';
}

const headers = rows.length ? Object.keys(rows[0]) : [];
function findKey(pred){ return headers.find(pred); }
const kEmail = findKey(h => strip(h).includes('mail'));
const kSoc   = findKey(h => strip(h).includes('soci'));
const kNom   = findKey(h => strip(h) === 'nom');
const kPre   = findKey(h => strip(h).includes('nom') && strip(h) !== 'nom');
const kMsg   = findKey(h => strip(h).includes('annonce') || strip(h).includes('diffuser'));
const kTel   = findKey(h => strip(h).includes('tel') || strip(h).includes('phone'));

function score(r){
  const email = strip(r[kEmail]);
  const soc   = strip(r[kSoc]);
  const nom   = strip(r[kNom]);
  const pre   = strip(r[kPre]);
  const msg   = strip(r[kMsg]);
  let s = 0;
  const at = email.indexOf('@');
  const domain = at > -1 ? email.slice(at+1) : '';
  const local  = at > -1 ? email.slice(0,at) : '';
  if (domain && FREE.indexOf(domain) === -1) s += 3;
  if (PRO_PREFIX.some(p => local.split(/[.\-_0-9]+/).indexOf(p) > -1)) s += 2;
  let e = 0; EMP.forEach(w => { if (msg.indexOf(w) > -1) e += 2; });
  s += Math.min(e, 4);
  let c = 0; CAND.forEach(w => { if (msg.indexOf(w) > -1) c += 3; });
  s -= Math.min(c, 6);
  const socClean = soc.replace(/[^a-z ]/g,'').trim();
  const isSelf = socClean && (socClean === nom || socClean === pre || socClean === (pre+' '+nom) || socClean === (nom+' '+pre));
  const junk = ['tous','aucun','aucune','na','n/a','-','neant','particulier','non societe','no','x'];
  if (!soc || isSelf || junk.indexOf(socClean) > -1) s -= 1;
  else if (socClean.length >= 3) s += 1;
  return s;
}

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const seen = new Set();
const out = [];

rows.forEach(r => {
  const email = strip(r[kEmail]);
  if (!EMAIL_RE.test(email)) return;
  if (score(r) < MIN_SCORE) return;
  if (seen.has(email)) return;
  seen.add(email);
