function normalizeUrl(raw) {
  try {
    const cleaned = String(raw || '').trim().replace(/&amp;/g, '&');
    const url = new URL(cleaned);
    url.hash = '';
    ['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content', 'fbclid', 'gclid'].forEach(param => url.searchParams.delete(param));
    return url.toString().replace(/\/$/, '');
  } catch (error) {
    return null;
  }
}

function extractUrls(body) {
  const text = String(body || '');
  const urls = [];
  const locRegex = new RegExp('<loc>\\s*([^<]+?)\\s*</loc>', 'gi');
  let match;
  while ((match = locRegex.exec(text)) !== null) urls.push(match[1]);
  const hrefRegex = new RegExp('href=["\\']([^"\\']+)["\\']', 'gi');
  while ((match = hrefRegex.exec(text)) !== null) urls.push(match[1]);
  return urls;
}

for (let i = 0; i < competitorsRaw.length; i++) {
  const source = competitorsRaw[i];
  const response = responses[i]?.json ?? {};
  const body = String(response.body ?? response.data ?? '');
  const statusCode = Number(response.statusCode ?? 0);
  const competitor = competitorMap.get(source.id) || source;
  const urls = extractUrls(body)
    .map(raw => {
      if (String(raw).startsWith('/')) return normalizeUrl('https://' + competitor.domain + raw);
      return normalizeUrl(raw);
    })
    .filter(Boolean)
    .filter(url => url.includes(competitor.domain))
    .filter(url => competitor.productUrlPatterns.some(pattern => url.includes(pattern)));

  for (const url of urls) {
    const key = competitor.id + '|' + url;
    if (!seen.has(key)) {
      seen.add(key);
      out.push({
        json: {
          competitorId: competitor.id,
          competitorName: competitor.name,
          domain: competitor.domain,
          url,
          sitemapStatusCode: statusCode,
          sourceUrl: source.sourceUrl,
          expectedTotal: competitor.expectedTotal
        }
      });
    }
  }
}

return out;

