// Accents must be stripped BEFORE collapsing to spaces, otherwise a
// combining mark becomes a space and splits the word.
function normalizeHeader(s){
  return (s || '').toString().toLowerCase()
    .normalize('NFD')
    .replace(/[^ -~]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}
function findKey(keys, includes, excludes){
  excludes = excludes || [];
  for (const k of keys){
    const words = normalizeHeader(k).split(' ');
    if (excludes.some(function(e){ return words.some(function(w){ return w.includes(e); }); })) continue;
    if (includes.some(function(inc){ return words.some(function(w){ return w.includes(inc); }); })) return k;
  }
  return null;
}
function findKeyAllWords(keys, requiredWords){
  for (const k of keys){
    const words = normalizeHeader(k).split(' ');
    if (requiredWords.every(function(rw){ return words.includes(rw); })) return k;
  }
  return null;
}

// Le formulaire ecrit l'heure sans zero initial avant 10 h :
// "2026-08-05 1:22:51". Ce n'est pas de l'ISO 8601, et Date() refuse la
// chaine sans rien dire. Resultat : toute candidature deposee entre
// minuit et 10 h perdait sa date, se retrouvait en tete du fichier RH
// avec une case Date vide, et cassait l'ordre chronologique.
function parseSubmissionTime(raw){
  const s = String(raw || '').trim();
  if (!s) return null;

  const m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})[ T](\d{1,2}):(\d{1,2})(?::(\d{1,2}))?/);
  if (m){
    const p = function(n){ return String(n).padStart(2, '0'); };
    const d = new Date(m[1] + '-' + p(m[2]) + '-' + p(m[3]) + 'T' + p(m[4]) + ':' + p(m[5]) + ':' + p(m[6] || 0));
    return isNaN(d.getTime()) ? null : d.toISOString();
  }

  const d = new Date(s.includes('T') ? s : s.replace(' ', 'T'));
  return isNaN(d.getTime()) ? null : d.toISOString();
}

function extractProfile(desc, desired){
  if (!desc || !desired) return '';
  const parts = desc.split(/^--- (.+?) ---$/m);
  const target = normalizeHeader(desired);
  if (!target) return '';
  let best = '';
  let bestScore = 0;
  for (let i = 1; i < parts.length; i += 2){
    const title = parts[i];
    const body = (parts[i + 1] || '').trim();
    const t = normalizeHeader(title).replace(/ h f$/, '').trim();
    let s = 0;
    if (t === target) s = 100;
    else if (t.indexOf(target) === 0 || target.indexOf(t) === 0) s = 80;
    else {
      const tw = t.split(' ');
      const dw = target.split(' ');
      s = dw.filter(function(w){ return w.length > 2 && tw.indexOf(w) !== -1; }).length * 10;
    }
    if (s > bestScore){ bestScore = s; best = title + '\n' + body; }
  }
  return bestScore >= 20 ? best : '';
}

