// La mention vit dans la recommandation, qui reste dans le dashboard,
// n'est pas exportee, et sert de marqueur persistant : c'est elle qui
// empeche un CV non lisible de disparaitre du fichier faute d'experience
// prouvee.
const SEUIL_TEXTE = 400;
const MARQUEUR = 'CV non lisible, évaluation basée sur le formulaire : ';
const SANS_INFO = 'Le formulaire ne donne aucune information sur le parcours professionnel.';

// Le modele a-t-il pu lire le document ? La branche vision repond
