function sansAccents(s) {
  return (s || '').toString().trim().toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g, '');
}

function porteLaMention(s) {
  const t = sansAccents(s);
  return t.indexOf('cv non lisible') === 0 || t.indexOf('cv illisible') === 0;
}

// Retire le prefixe de mention et rend ce qui suit les deux-points.
function retirerMention(s) {
  if (!porteLaMention(s)) return s;
  const i = s.indexOf(':');
  const reste = i === -1 ? '' : s.slice(i + 1).trim();
  if (reste.length < 40) return '';
  return reste.charAt(0).toUpperCase() + reste.slice(1);
}

const texteExtrait = texteCvExtrait();
const documentNonLu = !luEnVision && texteExtrait !== null && texteExtrait.trim().length < SEUIL_TEXTE;

let score = parsed.error ? null : parsed.score;
let summary = parsed.error ? '' : (parsed.summary || '').trim();
let recommendation = parsed.error ? parsed.error : (parsed.recommendation || '').trim();

if (parsed.error) {
  // Reponse IA inexploitable ou format de CV non pris en charge : le
