  summary = 'Le CV n\'a pas pu être ouvert par le système : ouvrir le CV manuellement pour évaluer le parcours.';
  recommendation = MARQUEUR + parsed.error + (json.visionErreur ? ' (' + json.visionErreur + ')' : '');
} else if (documentNonLu) {
  summary = retirerMention(summary) || SANS_INFO;
  if (!porteLaMention(recommendation)) {
    recommendation = MARQUEUR + (recommendation || 'ouvrir le CV manuellement pour vérifier le parcours.');
  }
  if (summary === SANS_INFO && typeof score === 'number' && score > 40) score = 40;
