  // ferait croire au recruteur que rien n'a ete lu, et exempterait a tort
  // le candidat du filtre d'experience.
  summary = retirerMention(summary) || summary;
  recommendation = retirerMention(recommendation) || recommendation;
}

// Ce que la suite de la chaine doit savoir : le fichier RH garde ces
