    job_title: candidate.jobTitle,
    candidate_name: candidate.name,
    first_name: candidate.firstName || '',
    last_name: candidate.lastName || '',
    email: candidate.email,
    phone: candidate.phone,
    city: candidate.city,
    desired_position: candidate.desiredPosition,
    suggested_position: parsed.error ? '' : (parsed.suggestedPosition || ''),
    experience_years: candidate.experienceYears,
    education_level: candidate.educationLevel,
    // Ecrit tel que le candidat l'a saisi : c'est la colonne que le
    // recruteur lit maintenant a la place de la synthese.
    message: candidate.message || '',
    cv_link: candidate.cvLink,
    cv_storage_path: cvStoragePath,
    submitted_at: candidate.submittedAt,
    score: score,
    relevant_experience: parsed.error ? false : parsed.relevantExperience === true,
    recommendation: recommendation,
    strengths: parsed.error ? '' : (Array.isArray(parsed.strengths) ? parsed.strengths.join(' | ') : ''),
    gaps: parsed.error ? '' : (Array.isArray(parsed.gaps) ? parsed.gaps.join(' | ') : ''),
    summary: summary,
    cv_unreadable: cvUnreadable,
    lu_en_vision: luEnVision,
    status: 'Nouveau',
    analyzed_at: new Date().toISOString()
  }
};

parameters.text:
=Offre : {{ $('Normalize Candidates').item.json.jobTitle }}

POSTE VISÉ PAR LE CANDIDAT : {{ $('Normalize Candidates').item.json.desiredPosition }}

FICHE DE CE POSTE (missions et profil recherché) :
{{ $('Normalize Candidates').item.json.jobProfile || $('Normalize Candidates').item.json.jobDescription }}

---
Candidat : {{ $('Normalize Candidates').item.json.name }}

{{ ($json.text || '').length < 400 ? '*** LE CV N A PAS PU ETRE LU (texte vide ou tronque). Tu ne disposes PAS du document. Evalue le candidat A PARTIR DES REPONSES AU FORMULAIRE ci-dessous et de rien d autre.\n- summary : redige la synthese sans aucun prefixe et sans dire que le CV est illisible, au declaratif (le candidat declare..., le formulaire ne precise pas...).\n- recommendation : commence IMPERATIVEMENT par "CV non lisible, evaluation basee sur le formulaire :".\n- Si le formulaire ne dit rien du parcours : score au maximum 40 et relevantExperience a false. ***' : '' }}

CV (texte extrait) — SEULE SOURCE FIABLE pour l'expérience et le niveau d'études quand il est lisible :
{{ $json.text }}

Réponses au formulaire (déclaratif, NON vérifié) :
{{ $('Normalize Candidates').item.json.extraAnswers }}
---

Évalue ce candidat par rapport à la fiche de poste ci-dessus : le score doit refléter son adéquation aux missions et au profil recherché de CE poste.

SOURCE DE VÉRITÉ : l'expérience et le niveau d'études se jugent EXCLUSIVEMENT sur le CV ; le nombre d'années déclaré dans le formulaire ne précise pas le secteur et ne prouve rien : ignore-le.

LIS LE CV EN ENTIER avant de conclure. Compte TOUS les postes listés, y compris les plus anciens et ceux exercés chez un même employeur. Un candidat ayant occupé six postes chez le même groupe a six postes d'expérience, pas un seul.

RÈGLE pour "relevantExperience" (le candidat a-t-il sa place chez ce recruteur ?), propre à cette offre :
{{ $('Normalize Candidates').item.json.experienceRule }}

ÉCRITURE DE "summary" — c'est la SEULE information qualitative que le recruteur recevra, elle doit lui permettre de décider s'il appelle ou non.
1. Le parcours COMPLET, poste par poste, du plus ancien au plus récent : pour CHACUN, la durée, l'intitulé et l'employeur. N'en omets AUCUN et n'en regroupe AUCUN : ni les stages, ni les postes courts, ni les plus anciens, même s'il y en a huit. Cette première phrase peut être longue, c'est normal et c'est voulu. Un poste absent est une information perdue pour le recruteur.
2. Ce qui correspond CONCRÈTEMENT aux missions de la fiche ci-dessus.
3. La réserve principale, formulée comme un fait vérifiable et jamais comme un jugement sur la personne. S'il n'y a pas de réserve sérieuse, dis ce qu'il reste à confirmer en entretien.
INTERDITS : répéter le score, répéter le nom du poste ou le nom du candidat, les formules creuses, et toute appréciation sur la personne elle-même.

ÉCRITURE DE "recommendation" : une ou deux phrases, ce que tu conseilles au recruteur de faire. NE RECOPIE PAS la synthèse.

Réponds UNIQUEMENT avec un objet JSON valide, sans texte autour, sans balises markdown, au format exact : {"score": <entier 0-100>, "relevantExperience": <true|false>, "recommendation": "1 ou 2 phrases, sans recopier la synthèse", "strengths": ["point fort"], "gaps": ["point faible"], "summary": "le parcours complet poste par poste, puis l'adéquation aux missions, puis la réserve"}

parameters.jsCode:
const BASE_URL = 'https://dreamjob.app.n8n.cloud/webhook/dreamjob-dashboard';
const ADMIN_USER = 'mehdi';
const ADMIN_PASS = 'QNeq1bLvpTd4wHbEfU63';

const rows = $input.all().map(i => i.json);

let reqJson = null;
let isAdminRoute = false;
try { reqJson = $('Dashboard Request (Admin)').item.json; isAdminRoute = true; } catch (e) { reqJson = null; }
if (!reqJson) {
  try { reqJson = $('Dashboard Request').item.json; } catch (e) { reqJson = null; }
}
const query = (reqJson && reqJson.query) || {};
const headers = (reqJson && reqJson.headers) || {};

function checkBasicAuth(hdrs, user, pass){
  const raw = hdrs.authorization || hdrs.Authorization || '';
  if (!raw.startsWith('Basic ')) return false;
  let decoded = '';
  try { decoded = Buffer.from(raw.slice(6), 'base64').toString('utf8'); } catch (e) { return false; }
  const idx = decoded.indexOf(':');
  if (idx === -1) return false;
  return decoded.slice(0, idx) === user && decoded.slice(idx + 1) === pass;
}

const adminAuthed = isAdminRoute && checkBasicAuth(headers, ADMIN_USER, ADMIN_PASS);
const needsAuthPrompt = isAdminRoute && !adminAuthed;

function tokenFor(str){
  let h = 5381;
  const s = String(str || '');
  for (let i = 0; i < s.length; i++){
    h = ((h * 33) ^ s.charCodeAt(i)) >>> 0;
  }
  return h.toString(36);
}

const jobs = Array.from(new Set(rows.map(r => r.job_title))).filter(Boolean);

const showAdminChrome = adminAuthed;

const rid = (query.rid || '').trim();
const isRecruiterView = !adminAuthed && !!rid;
let recruiterJob = null;
if (isRecruiterView) {
  recruiterJob = jobs.find(function(j){ return tokenFor(j) === rid; }) || null;
}
const linkValid = adminAuthed || (isRecruiterView && !!recruiterJob);

const jobFilter = (query.job || '').toLowerCase();

let filtered;
if (adminAuthed) {
  filtered = rows.filter(r => r.job_title);
  if (jobFilter) {
    filtered = filtered.filter(r => (r.job_title || '').toLowerCase().includes(jobFilter));
  }
} else if (isRecruiterView && recruiterJob) {
  filtered = rows.filter(function(r){ return r.job_title === recruiterJob; });
} else {
  filtered = [];
}
filtered.sort((a, b) => (Number(b.score) || -1) - (Number(a.score) || -1));

function esc(s){
  return (s === undefined || s === null ? '' : String(s))
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
function scoreClass(score){
  const s = Number(score);
  if (isNaN(s)) return 'none';
  if (s >= 75) return 'good';
  if (s >= 50) return 'mid';
  return 'low';
}
function splitTags(s){
  return (s || '').split('|').map(function(t){ return t.trim(); }).filter(Boolean);
}
function tagsHtml(list, cls){
  return list.map(function(t){ return '<span class="tag ' + cls + '">' + esc(t) + '</span>'; }).join('');
}

const scored = filtered.filter(function(r){ return r.score !== '' && r.score !== undefined && !isNaN(Number(r.score)); });
const avgScore = scored.length ? Math.round(scored.reduce(function(sum, r){ return sum + Number(r.score); }, 0) / scored.length) : null;
const strongCount = scored.filter(function(r){ return Number(r.score) >= 75; }).length;
const unreadCount = filtered.filter(function(r){ return (r.status || '').toLowerCase() === 'nouveau'; }).length;

const analyzedTimes = filtered.map(function(r){ return r.analyzed_at; }).filter(Boolean).map(function(t){ return new Date(t); }).filter(function(d){ return !isNaN(d); });
let lastAnalyzed = '';
if (analyzedTimes.length){
  const latestMs = Math.max.apply(null, analyzedTimes.map(function(d){ return d.getTime(); }));
  lastAnalyzed = new Date(latestMs).toLocaleString('fr-FR', { day:'2-digit', month:'2-digit', year:'numeric', hour:'2-digit', minute:'2-digit' });
}

const cardsHtml = filtered.map(function(r){
  const sc = scoreClass(r.score);
  const hasScore = r.score !== '' && r.score !== undefined && !isNaN(Number(r.score));
  const scoreDisplay = hasScore ? esc(r.score) : '—';
  const statusClass = (r.status || '').toLowerCase() === 'nouveau' ? 'nouveau' : 'other';
  const statusLabel = r.status ? esc(r.status).toUpperCase() : 'EN COURS';
  const metaParts = [];
  if (r.city) metaParts.push(esc(r.city));
  if (r.experience_years) metaParts.push(esc(r.experience_years) + (isNaN(Number(r.experience_years)) ? '' : (Number(r.experience_years) > 1 ? ' ans d\'expérience' : ' an d\'expérience')));
  if (r.email) metaParts.push(esc(r.email));
  const bodyText = r.summary || r.recommendation || '';
  const searchBlob = esc([r.candidate_name, r.city, r.email, r.desired_position, r.job_title].filter(Boolean).join(' ').toLowerCase());

  return '<div class="card" data-search="' + searchBlob + '">' +
    '<div class="score-badge ' + sc + '">' + scoreDisplay + '</div>' +
    '<div class="card-main">' +
      '<div class="card-head"><span class="cand-name">' + esc(r.candidate_name || 'Sans nom') + '</span><span class="cand-job">' + esc(r.job_title) + '</span></div>' +
      (metaParts.length ? '<div class="cand-meta">' + metaParts.map(function(p){ return '<span>' + p + '</span>'; }).join('') + '</div>' : '') +
      (bodyText ? '<div class="summary">' + esc(bodyText) + '</div>' : '') +
      '<div class="tags">' + tagsHtml(splitTags(r.strengths), 'strength') + tagsHtml(splitTags(r.gaps), 'gap') + '</div>' +
    '</div>' +
    '<div class="card-side">' +
      '<span class="status-pill ' + statusClass + '">' + statusLabel + '</span>' +
      (r.cv_link ? '<a class="cv-link" href="' + esc(r.cv_link) + '" target="_blank" rel="noopener">Voir le CV →</a>' : '') +
    '</div>' +
  '</div>';
}).join('');

const filterLinks = jobs.map(function(j){
  const isActive = jobFilter && j.toLowerCase().includes(jobFilter);
  return '<a href="?job=' + encodeURIComponent(j) + '" class="chip' + (isActive ? ' active' : '') + '">' + esc(j) + '</a>';
}).join('');
const allActiveClass = jobFilter ? '' : ' active';

const shareRowsHtml = jobs.map(function(j, idx){
  const link = BASE_URL + '?rid=' + tokenFor(j);
  return '<div class="share-row">' +
    '<span class="share-job">' + esc(j) + '</span>' +
    '<code class="share-link" id="dj-link-' + idx + '">' + esc(link) + '</code>' +
    '<button type="button" class="copy-btn" data-target="dj-link-' + idx + '">Copier</button>' +
  '</div>';
}).join('');
const shareHtml = jobs.length ?
  '<div class="share-panel">' +
    '<div class="share-title">Liens à partager par offre (chaque recruteur ne voit que sa liste)</div>' +
    shareRowsHtml +
  '</div>' : '';

const statsHtml =
  '<div class="stats">' +
    '<div class="stat"><div class="label">Candidats</div><div class="value">' + filtered.length + '</div></div>' +
    '<div class="stat"><div class="label">Score moyen</div><div class="value accent">' + (avgScore === null ? '—' : avgScore) + '</div></div>' +
    '<div class="stat"><div class="label">Profils forts (&ge;75)</div><div class="value">' + strongCount + '</div></div>' +
    '<div class="stat"><div class="label">Non lus</div><div class="value">' + unreadCount + '</div></div>' +
  '</div>';

const searchBarHtml =
  '<div class="search"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"></circle><line x1="21" y1="21" x2="16.65" y2="16.65"></line></svg>' +
  '<input type="text" id="dj-search" placeholder="Rechercher un candidat, une ville…" /></div>';

const toolbarHtml = showAdminChrome
  ? ('<div class="toolbar">' + searchBarHtml +
      '<div class="chip-row"><a href="?" class="chip' + allActiveClass + '">Toutes les offres</a>' + filterLinks + '</div>' +
    '</div>')
  : ('<div class="toolbar">' + searchBarHtml + '</div>');

const topbarRightHtml = showAdminChrome
  ? ((lastAnalyzed ? 'Dernière analyse : <b>' + esc(lastAnalyzed) + '</b><br>' : '') + jobs.length + ' offre(s) suivie(s)')
  : (lastAnalyzed ? 'Dernière analyse : <b>' + esc(lastAnalyzed) + '</b>' : '');

const bodyHtml = needsAuthPrompt
  ? '<div class="content"><div class="empty" style="display:block;">Authentification requise.</div></div>'
  : (!linkValid
    ? '<div class="content"><div class="empty" style="display:block;">Lien invalide ou expiré. Contactez DreamJob pour obtenir un nouveau lien.</div></div>'
    : (
        statsHtml +
        toolbarHtml +
        (showAdminChrome ? shareHtml : '') +
        '<div class="content">' +
          '<div class="cards" id="dj-cards">' + (cardsHtml || '') + '</div>' +
          '<div class="empty" id="dj-empty-all">Aucun candidat pour le moment.</div>' +
          '<div class="empty" id="dj-empty-search">Aucun résultat pour cette recherche.</div>' +
        '</div>'
      )
  );

const html = '<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8">' +
'<meta name="viewport" content="width=device-width, initial-scale=1">' +
