const candidates = $input.all();
const existing = $('Get Existing Candidates (Supabase)').all();
const existingKeys = new Set(existing.map(function(it){ return it.json.cv_link || ''; }));

const seenThisRun = new Set();
const result = [];
for (const it of candidates) {
  const key = it.json.cvLink || '';
  if (existingKeys.has(key)) continue;
  if (seenThisRun.has(key)) continue;
  seenThisRun.add(key);
  result.push(it);
}
return result;

// A .docx is a ZIP archive; the document body lives in word/document.xml.
// Move that entry's binary reference to 'data' so Extract From File can
// read it, without decoding the buffer here.
const bin = $input.item.binary || {};
const keys = Object.keys(bin);

let key = null;
for (const k of keys) {
  const name = ((bin[k].fileName || '') + ' ' + k).toLowerCase();
  if (name.includes('document.xml') && !name.includes('rels')) { key = k; break; }
}

if (!key) {
  return { json: { docxFailed: true, text: '' } };
}

return { json: { docxFailed: false }, binary: { data: bin[key] } };

// Turn the Word XML body into plain text for the scoring prompt:
// paragraph tags become line breaks, every other tag is dropped.
const xml = $input.item.json.docxXml || '';

let t = xml.split('</w:p>').join('\n');
t = t.split('<w:br/>').join('\n');
t = t.replace(/<[^>]+>/g, '');
t = t.split('&amp;').join('&')
     .split('&lt;').join('<')
     .split('&gt;').join('>')
     .split('&quot;').join('"')
     .split('&apos;').join("'")
     .split('&#39;').join("'");
t = t.replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();

return { json: { text: t.slice(0, 20000) } };

// The Compression node picks its archive format from the file extension and
// rejects ".docx" outright — but a .docx IS a zip archive, so hand it the
// exact same bytes labelled as one.
const bin = ($input.item.binary || {}).data;
if (!bin) return { json: { docxFailed: true } };

return {
  json: { docxFailed: false },
  binary: {
    data: Object.assign({}, bin, {
      fileName: 'cv.zip',
      fileExtension: 'zip',
      mimeType: 'application/zip'
    })
  }
};

// Reconstruit l'integralite du fichier RH de CETTE offre dans l'ordre
// chronologique. Necessaire parce qu'un simple append place toujours les
// nouveaux candidats en bas : l'ordre ne peut etre garanti qu'en
// reecrivant tout.
//
// La config vient de « Config de l'offre », jamais de la boucle sur les
// offres : quand ce noeud s'execute, la boucle a deja fini et sa sortie
// ne contient plus l'offre.
const cfg = $('Config de l\'offre').first().json;
const crit = cfg.exportCriteria || {};
const VILLES = Array.isArray(crit.cities) ? crit.cities : [];
const EXIGE_EXPERIENCE = crit.require_relevant_experience !== false;
const DESTINATION = cfg.exportSheetUrl;

// Le noeud Google Sheets associe les valeurs aux colonnes par le nom de
// l'en-tete. Une colonne absente n'est pas une erreur pour lui : elle est
// silencieusement ignoree, et le recruteur recoit un fichier a moitie
// vide sans que personne ne s'en apercoive. On verifie donc avant.
//
// Le fichier ne porte plus le score ni la synthese de l'IA : la colonne
// qualitative est le message ecrit par le candidat lui-meme. Score et
// synthese restent en base et sur le dashboard.
const EN_TETES = [
  'Date', 'Nom', 'Prénom', 'Email', 'Téléphone', 'Ville',
  'Poste', 'Expérience', 'Etudes', 'Message', 'CV'
];

const lignesExistantes = $('Lire la feuille actuelle').all()
  .filter(function (i) { return i.json && i.json.row_number; });

if (lignesExistantes.length) {
  const presentes = Object.keys(lignesExistantes[0].json);
  const manquantes = EN_TETES.filter(function (h) { return presentes.indexOf(h) === -1; });
  if (manquantes.length) {
    throw new Error(
      'En-tetes incorrects dans le fichier RH de l\'offre "' + (cfg.jobTitle || '') + '". ' +
      'Colonnes manquantes : ' + manquantes.join(', ') + '. ' +
      'Aucune ligne n\'a ete ecrite, le fichier est intact. ' +
      'Collez ceci en ligne 1 du Google Sheet : ' + EN_TETES.join(' | ')
    );
  }
}

function norm(s) {
  return (s || '').toString().toLowerCase().normalize('NFD').replace(/[^a-z0-9 ]/g, '');
}

// Liste de villes vide = aucun filtre geographique pour cette offre.
function inZone(city) {
  if (!VILLES.length) return true;
  const c = norm(city);
  return VILLES.some(function (v) { return c.indexOf(v) !== -1; });
}

// Un CV que le systeme n'a pas su ouvrir ne prouve pas l'experience : le
// filtre d'experience le rejetterait, et le candidat disparaitrait du
// fichier sans que personne ne sache pourquoi. La marque est en tete de
// recommendation, champ qui n'est pas exporte.
function debut(s) {
  return (s || '').toString().trim().toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g, '');
}
function cvNonLisible(c) {
  const champs = [debut(c.recommendation), debut(c.summary)];
  return champs.some(function (t) {
    return t.indexOf('cv non lisible') === 0 || t.indexOf('cv illisible') === 0;
  });
}

// submitted_at est un ISO ; la feuille attend du JJ/MM/AAAA HH:MM:SS
function frDate(s) {
  if (!s) return '';
  const p = String(s).slice(0, 10).split('-');
  if (p.length !== 3) return '';
  return p[2] + '/' + p[1] + '/' + p[0] + ' ' + String(s).slice(11, 19);
}

// Une chaine vide se classe avant toutes les dates : un candidat sans
// date remontait donc en tete du fichier, a l'endroit le plus visible et
// le moins logique. Il passe desormais en fin de liste.
function parDate(a, b) {
  const da = String(a.submitted_at || '');
  const db = String(b.submitted_at || '');
  if (!da && !db) return 0;
  if (!da) return 1;
  if (!db) return -1;
  return da.localeCompare(db);
}

function txt(v) {
  if (v === null || v === undefined) return '';
  return String(v);
}

function ligne(rowNumber, c) {
  return {
    // Porte la destination sur chaque ligne : le noeud d'ecriture la lit
    // depuis l'item, sans dependre d'aucun etat de boucle.
    exportSheetUrl: DESTINATION,
    row_number: rowNumber,
    Date: c ? frDate(c.submitted_at) : '',
    // Le formulaire donne Nom et Prenom separement ; les anciennes
    // lignes n'ont que le nom complet, qui reste alors dans « Nom ».
    Nom: c ? txt(c.last_name || c.candidate_name) : '',
    'Prénom': c ? txt(c.first_name) : '',
    Email: c ? txt(c.email) : '',
    'Téléphone': c ? txt(c.phone) : '',
    Ville: c ? txt(c.city) : '',
    Poste: c ? txt(c.desired_position) : '',
    'Expérience': c ? txt(c.experience_years) : '',
    // Repris tel quel du formulaire, comme l'experience declaree.
    Etudes: c ? txt(c.education_level) : '',
    Message: c ? txt(c.message) : '',
    CV: c ? txt(c.cv_link) : ''
  };
}

const retenus = $('Lire candidats retenus (Supabase)').all()
  .map(function (i) { return i.json; })
  .filter(function (c) {
    if (!c || c.archived_at) return false;
    if (EXIGE_EXPERIENCE && c.relevant_experience !== true && !cvNonLisible(c)) return false;
    return inZone(c.city);
  })
  .sort(parDate);

const out = retenus.map(function (c, idx) {
  return { json: ligne(idx + 2, c) };
});

// Si la liste a retreci (candidat archive), on blanchit les lignes en trop
// plutot que de laisser des doublons trainer en bas de la feuille.
for (let r = out.length + 2; r < lignesExistantes.length + 2; r++) {
  out.push({ json: ligne(r, null) });
}

return out;

// Une offre n'est scannee que si elle a un formulaire source a lire et
// qu'elle n'a pas depasse sa date. L'expiration arrete le scan et rien
// d'autre : les candidats deja collectes et le fichier RH restent intacts.
const now = Date.now();

return $input.all().filter(function (item) {
  const job = item.json || {};
  if (!job.source_sheet_url) return false;
  if (job.expires_at && new Date(job.expires_at).getTime() <= now) return false;
  return true;
});

// Sort la destination et les criteres de l'offre sur l'item lui-meme.
// Toute la chaine d'export lit ensuite $json, jamais l'etat de la boucle
// sur les offres, qui a deja bascule sur sa sortie « termine » a ce stade.
const cfg = $('Normalize Candidates').item.json;

return {
  json: {
    jobId: cfg.jobId,
    jobTitle: cfg.jobTitle,
    exportSheetUrl: cfg.exportSheetUrl,
    exportCriteria: cfg.exportCriteria || {}
  }
};

// Branche de rejet du filtre d'export. Rejeter tout le monde est
// legitime : personne dans la zone, personne avec l'experience requise,
// ou pas de fichier RH configure pour cette offre.
//
// Ce qui ne l'est pas, c'est de rejeter tout le monde parce que la
// configuration n'a pas ete resolue. C'est ce qui s'est produit le
// 04/08 entre 19h et 21h : export_sheet_url arrivait vide, le filtre
// rejetait chaque candidat, et l'execution se terminait en succes.
// Sans ce controle, la panne est invisible.
const cfg = $('Normalize Candidates').first().json;
const offres = $('Filtrer offres scannables').all().map(function (i) { return i.json; });
const offre = offres.filter(function (j) { return j.id === cfg.jobId; })[0];

if (offre && offre.export_sheet_url && !cfg.exportSheetUrl) {
  throw new Error(
    'Configuration d\'export non resolue pour l\'offre "' + (offre.title || '') + '". ' +
    'L\'offre possede un fichier RH mais la chaine ne le voit pas : ' +
    $input.all().length + ' candidat(s) ont ete rejetes sans etre exportes. ' +
    'Le fichier RH n\'a pas ete mis a jour.'
  );
}

return [];

// Le statut « succes » de n8n ne prouve pas que le fichier a recu quoi
// que ce soit : le noeud Sheets peut ecrire dans le vide si une colonne
// n'est pas reconnue, ou si la destination n'est pas celle qu'on croit.
// On relit donc le fichier et on compare a ce qu'on vient d'y mettre.
//
// La comparaison porte sur QUI est present, pas sur combien : un simple
// ecart de compte (« 12 attendues, 11 relues ») ne dit pas quelle ligne
// manque, et laisse le diagnostic a faire a la main.
const attendues = $('Construire la feuille triee').all()
  .map(function (i) { return i.json; })
  .filter(function (r) { return r.Nom || r.Email || r.CV; });

const relues = $input.all()
  .map(function (i) { return i.json; })
  .filter(function (r) { return r && (r.Nom || r.Email || r.CV); });

const cfg = $('Config de l\'offre').first().json;

// Le lien du CV est unique par candidat et par offre ; l'email puis le
// couple nom + date prennent le relais pour les lignes anciennes.
function cle(r) {
  const c = (r.CV || '').toString().trim();
  if (c) return 'cv:' + c.toLowerCase();
  const e = (r.Email || '').toString().trim();
  if (e) return 'email:' + e.toLowerCase();
  return 'nom:' + (r.Nom || '').toString().trim().toLowerCase() + '|' + (r.Date || '');
}

function etiquette(r) {
  return ((r.Nom || '') + ' ' + (r['Prénom'] || '')).trim() || r.Email || r.CV || '(ligne vide)';
}

const clesRelues = new Set(relues.map(cle));
const clesAttendues = new Set(attendues.map(cle));

const absentes = attendues.filter(function (r) { return !clesRelues.has(cle(r)); });
const enTrop = relues.filter(function (r) { return !clesAttendues.has(cle(r)); });

function liste(rows) {
  const noms = rows.slice(0, 5).map(etiquette);
  if (rows.length > 5) noms.push('et ' + (rows.length - 5) + ' autre(s)');
  return noms.join(', ');
}

if (absentes.length || enTrop.length) {
  const details = [];
  if (absentes.length) {
    details.push(absentes.length + ' ligne(s) attendue(s) absente(s) du fichier : ' + liste(absentes));
  }
  if (enTrop.length) {
    details.push(enTrop.length + ' ligne(s) presente(s) dans le fichier sans etre attendue(s) : ' + liste(enTrop));
  }
  throw new Error(
    'Ecriture non confirmee pour l\'offre "' + (cfg.jobTitle || '') + '". ' +
    attendues.length + ' ligne(s) devaient etre presentes, ' + relues.length + ' relue(s). ' +
    details.join(' ; ') + '. ' +
    'Verifiez les en-tetes et les droits d\'acces du fichier : ' + (cfg.exportSheetUrl || '(aucune destination)')
  );
}

// Verifier aussi l'ordre : le premier et le dernier doivent correspondre.
if (attendues.length) {
  const premierAttendu = String(attendues[0].Nom || '');
  const premierRelu = String(relues[0].Nom || '');
  const dernierAttendu = String(attendues[attendues.length - 1].Nom || '');
  const dernierRelu = String(relues[relues.length - 1].Nom || '');
  if (premierAttendu !== premierRelu || dernierAttendu !== dernierRelu) {
    throw new Error(
      'Le fichier RH de l\'offre "' + (cfg.jobTitle || '') + '" n\'est pas dans l\'ordre attendu. ' +
      'Premiere ligne attendue "' + premierAttendu + '", relue "' + premierRelu + '". ' +
      'Derniere attendue "' + dernierAttendu + '", relue "' + dernierRelu + '".'
    );
  }
}

return [{ json: {
  offre: cfg.jobTitle,
  lignesConfirmees: relues.length,
  destination: cfg.exportSheetUrl
} }];

// Le binaire vient directement du telechargement initial, via le
// routeur : inutile de retelecharger le fichier. Cette instance stocke
// les binaires sur disque, item.binary.data.data ne contient donc pas le
// base64 mais une reference : il faut charger le buffer explicitement.
//
// Tous les PDF passent par ici. L'extraction de texte aplatissait les
// mises en page a colonnes et decalait les couples employeur-role d'un
// cran, sans que rien ne permette de le detecter : le resultat avait
// l'air correct. Le modele voit desormais la page telle qu'elle est.
function prompt(c) {
  const L = [];
  L.push('Offre : ' + (c.jobTitle || ''));
  L.push('');
  L.push('POSTE VISE PAR LE CANDIDAT : ' + (c.desiredPosition || ''));
  L.push('');
  L.push('FICHE DE CE POSTE (missions et profil recherche) :');
  L.push(c.jobProfile || c.jobDescription || '');
  L.push('');
  L.push('---');
  L.push('Candidat : ' + (c.name || ''));
  L.push('');
  L.push('Le CV est le document ci-joint, SEULE SOURCE FIABLE pour l experience et le niveau d etudes.');
  L.push('');
  L.push('MISE EN PAGE : beaucoup de CV sont sur deux colonnes, les durees d un cote et les employeurs de l autre. Chaque duree et chaque intitule appartiennent a l employeur en face duquel ils figurent : suis la mise en page du document, ne decale jamais une duree d un employeur au suivant.');
  L.push('');
  L.push('CHAMP documentLisible : mets true des que tu parviens a lire le document, meme partiellement, meme s il est pauvre. Un CV que tu as lu et qui ne contient simplement aucune experience pertinente reste LISIBLE : mets true. Ne mets false que si tu ne distingues aucun contenu exploitable (page blanche, image floue, document qui n est pas un CV).');
  L.push('');
  L.push('SI ET SEULEMENT SI documentLisible vaut false : evalue le candidat a partir des reponses au formulaire ci-dessous et de rien d autre ; redige summary sans aucun prefixe et sans dire que le CV est illisible, au declaratif (le candidat declare..., le formulaire ne precise pas...) ; commence recommendation par "CV non lisible, evaluation basee sur le formulaire :" ; si le formulaire ne dit rien du parcours, score au maximum 40 et relevantExperience a false.');
  L.push('');
  L.push('Reponses au formulaire (declaratif, NON verifie) :');
  L.push(c.extraAnswers || '');
  L.push('---');
  L.push('');
  L.push('Evalue ce candidat par rapport a la fiche de poste ci-dessus : le score doit refleter son adequation aux missions et au profil recherche de CE poste.');
  L.push('');
  L.push('SOURCE DE VERITE : l experience et le niveau d etudes se jugent EXCLUSIVEMENT sur le CV ; le nombre d annees declare dans le formulaire ne precise pas le secteur et ne prouve rien : ignore-le.');
  L.push('');
  L.push('REGLE pour relevantExperience (le candidat a-t-il sa place chez ce recruteur ?), propre a cette offre :');
  L.push(c.experienceRule || '- true si le parcours correspond au secteur decrit par la fiche de poste, false sinon.');
  L.push('');
  L.push('ECRITURE DE summary : c est la SEULE information qualitative que le recruteur recevra, elle doit lui permettre de decider s il appelle ou non.');
  L.push('1. Le parcours COMPLET, poste par poste, du plus ancien au plus recent : pour CHACUN, la duree, l intitule et l employeur. N en omets AUCUN et n en regroupe AUCUN : ni les stages, ni les postes courts, ni les plus anciens, meme s il y en a huit. Cette premiere phrase peut etre longue, c est normal et c est voulu. Un poste absent est une information perdue pour le recruteur.');
  L.push('2. Ce qui correspond CONCRETEMENT aux missions de la fiche ci-dessus.');
  L.push('3. La reserve principale, formulee comme un fait verifiable et jamais comme un jugement sur la personne. S il n y a pas de reserve serieuse, dis ce qu il reste a confirmer en entretien.');
  L.push('INTERDITS : repeter le score, repeter le nom du poste ou le nom du candidat, les formules creuses, et toute appreciation sur la personne elle-meme.');
  L.push('');
  L.push('ECRITURE DE recommendation : une ou deux phrases, ce que tu conseilles au recruteur de faire. NE RECOPIE PAS la synthese et ne redonne pas la liste des postes : les deux champs s affichent cote a cote, la repetition ne lui apprend rien.');
  L.push('');
  L.push('Reponds UNIQUEMENT avec un objet JSON valide, sans texte autour, sans balises markdown, au format exact : {"documentLisible": <true|false>, "score": <entier 0-100>, "relevantExperience": <true|false>, "recommendation": "1 ou 2 phrases, sans recopier la synthese", "strengths": ["point fort"], "gaps": ["point faible"], "summary": "le parcours complet poste par poste, puis l adequation aux missions, puis la reserve"}');
  return L.join('\n');
}

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');

  // Seuls quelques CV empruntent cette branche : leur position ici n'est
  // pas celle de la liste complete des candidats. On passe donc par
  // l'appariement plutot que par l'index.
  let c = {};
  try { c = $('Normalize Candidates').itemMatching(i).json; } catch (e) { c = {}; }

  // Un CV pese quelques centaines de kilo-octets. Au-dela, ce n'est plus
  // un CV : mieux vaut une erreur nommee qu'une requete de 20 Mo.
  if (buffer.length > 8000000) {
    throw new Error('CV trop volumineux pour la lecture vision (' + Math.round(buffer.length / 1000000) + ' Mo) : ' + (c.cvLink || ''));
  }

  out.push({ json: { octets: buffer.length, body: {
    model: 'gpt-4.1-mini',
    temperature: 0,
    text: { format: { type: 'json_object' } },
    input: [
      { role: 'system', content: [{ type: 'input_text', text: 'Tu es un assistant de recrutement. Tu analyses des CV et reponds uniquement en JSON valide, sans texte ni markdown autour.' }] },
      { role: 'user', content: [
        { type: 'input_file', filename: 'cv.pdf', file_data: 'data:application/pdf;base64,' + buffer.toString('base64') },
        { type: 'input_text', text: prompt(c) }
      ] }
    ]
  } }, pairedItem: i });
}

return out;

// Ramene la reponse de l'API Responses au format que les agents
// produisent, pour que « Parse AI Result & Build Row » traite les trois
// branches de la meme facon.
const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const r = items[i].json || {};
  let texte = typeof r.output_text === 'string' ? r.output_text : '';
  if (!texte && Array.isArray(r.output)) {
    for (const o of r.output) {
      if (Array.isArray(o.content)) {
        for (const c of o.content) { if (typeof c.text === 'string') texte += c.text; }
      }
    }
  }

  // L'appel peut echouer (reseau, quota) : on ne perd pas le candidat, on
  // laisse la suite de la chaine retomber sur l'evaluation par le
  // formulaire, mention comprise.
  const ok = !!texte && texte.indexOf('{') !== -1;

  out.push({ json: {
    aiRawText: ok ? texte : '',
    // Dit a l'etape suivante que le modele a bien eu le document sous les
    // yeux : sans ce drapeau elle verrait un texte extrait vide et
    // imposerait la mention « CV non lisible » a une lecture reussie.
    visionOk: ok,
    visionErreur: ok ? null : (r.error && r.error.message) || r.message || 'reponse vision vide'
  }, pairedItem: i });
}

return out;

// Le depot et sa copie convertie ne servent qu'au temps de la
// conversion. On les efface juste apres l'export : le CV est deja lu a
// ce stade, plus rien n'en depend.
const out = [];
for (let i = 0; i < $input.all().length; i++) {
  let idDepot = null;
  let idCopie = null;
  try { idDepot = $('Deposer le doc sur Drive').all()[i].json.id; } catch (e) {}
  try { idCopie = $('Convertir le doc en Google Doc').all()[i].json.id; } catch (e) {}
  if (idCopie) out.push({ json: { id: idCopie } });
  if (idDepot) out.push({ json: { id: idDepot } });
