  const isSelf = socClean && (socClean === nom || socClean === pre || socClean === (pre+' '+nom) || socClean === (nom+' '+pre));
  const junk = ['tous','aucun','aucune','na','n/a','-','néant','neant','particulier'];
  if (!soc || isSelf || junk.indexOf(socClean) > -1) s -= 1;
  else if (socClean.length >= 3) s += 1;
  return s;
}

