function slugTokens(u){
  if(!u) return [];
  try{
    const path = new URL(String(u)).pathname;
    const parts = path.split('/').filter(Boolean);
    const slug = parts.length ? parts[parts.length-1] : '';
    return slug.toLowerCase().replace(/[^a-z0-9-]+/g,'-').split('-').filter(Boolean);
  }catch(e){ return []; }
}

function coreFromTokens(tokens){
  let t = tokens.filter(x => !GENERIC.has(x));
  // retire les tokens purement numeriques (tailles de pack) si au moins 2 tokens restent
  const noDigits = t.filter(x => !/^\d+$/.test(x));
  if(noDigits.length >= 2) t = noDigits;
  return t.join(' ').trim();
}

