function norm(s) { return (s || '').toString().toLowerCase().normalize('NFD').replace(/[^a-z0-9 ]/g, ''); }
function inZone(city) { if (!VILLES.length) return true; const c = norm(city); return VILLES.some(function (v) { return c.indexOf(v) !== -1; }); }

// Meme regle que le scanner : un CV que le systeme n a pas su ouvrir ne
// prouve pas l experience, mais le candidat doit rester visible dans le
// fichier. La marque est en tete de recommendation, champ non exporte.
function debut(s) { return (s || '').toString().trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, ''); }
function cvNonLisible(c) {
  return [debut(c.recommendation), debut(c.summary)].some(function (t) {
    return t.indexOf('cv non lisible') === 0 || t.indexOf('cv illisible') === 0;
  });
}

function frDate(s) { if (!s) return ''; const p = String(s).slice(0,10).split('-'); if (p.length !== 3) return ''; return p[2] + '/' + p[1] + '/' + p[0] + ' ' + String(s).slice(11,19); }
function txt(v) { return (v === null || v === undefined) ? '' : String(v); }

// Une chaine vide se classe avant toutes les dates : un candidat sans
// date remontait donc en tete du fichier. Il passe en fin de liste.
function parDate(a, b) {
  const da = String(a.submitted_at || '');
  const db = String(b.submitted_at || '');
  if (!da && !db) return 0;
  if (!da) return 1;
  if (!db) return -1;
  return da.localeCompare(db);
}

function ligne(rowNumber, c) {
  return {
    exportSheetUrl: DESTINATION,
    row_number: rowNumber,
    Date: c ? frDate(c.submitted_at) : '',
    Nom: c ? txt(c.last_name || c.candidate_name) : '',
    'Prénom': c ? txt(c.first_name) : '',
    Email: c ? txt(c.email) : '',
    'Téléphone': c ? txt(c.phone) : '',
    Ville: c ? txt(c.city) : '',
    Poste: c ? txt(c.desired_position) : '',
    'Expérience': c ? txt(c.experience_years) : '',
    Etudes: c ? txt(c.education_level) : '',
    Message: c ? txt(c.message) : '',
    CV: c ? txt(c.cv_link) : ''
  };
}

