function cle(r) {
  const c = (r.CV || '').toString().trim();
  if (c) return 'cv:' + c.toLowerCase();
  const e = (r.Email || '').toString().trim();
  if (e) return 'email:' + e.toLowerCase();
  return 'nom:' + (r.Nom || '').toString().trim().toLowerCase() + '|' + (r.Date || '');
}
function etiquette(r) { return ((r.Nom || '') + ' ' + (r['Prénom'] || '')).trim() || r.Email || r.CV || '(ligne vide)'; }

const clesRelues = new Set(relues.map(cle));
const clesAttendues = new Set(attendues.map(cle));
const absentes = attendues.filter(function (r) { return !clesRelues.has(cle(r)); });
const enTrop = relues.filter(function (r) { return !clesAttendues.has(cle(r)); });

if (absentes.length || enTrop.length) {
  const d = [];
  if (absentes.length) d.push(absentes.length + ' absente(s) : ' + absentes.slice(0, 5).map(etiquette).join(', '));
  if (enTrop.length) d.push(enTrop.length + ' en trop : ' + enTrop.slice(0, 5).map(etiquette).join(', '));
  throw new Error('Ecriture non confirmee : ' + attendues.length + ' ligne(s) attendues, ' + relues.length + ' relue(s). ' + d.join(' ; '));
}

