/* -------------------------------------------------------------------------- */
/* Normalisation                                                               */
/* -------------------------------------------------------------------------- */

// Entites nommees courantes dans le HTML rendu par WordPress (le champ
// `content.rendered` encode systematiquement les accents francais).
const NAMED_ENTITIES = {
  agrave: 'à', aacute: 'á', acirc: 'â', atilde: 'ã', auml: 'ä', aring: 'å', aelig: 'æ',
  ccedil: 'ç', egrave: 'è', eacute: 'é', ecirc: 'ê', euml: 'ë',
  igrave: 'ì', iacute: 'í', icirc: 'î', iuml: 'ï', ntilde: 'ñ',
  ograve: 'ò', oacute: 'ó', ocirc: 'ô', otilde: 'õ', ouml: 'ö', oelig: 'œ',
  ugrave: 'ù', uacute: 'ú', ucirc: 'û', uuml: 'ü', yuml: 'ÿ',
  szlig: 'ß', laquo: '«', raquo: '»', hellip: '…', ndash: '–', mdash: '—',
  lsquo: '‘', rsquo: '’', ldquo: '“', rdquo: '”', deg: '°', euro: '€',
  middot: '·', bull: '•', trade: '™', copy: '©', reg: '®',
};

function decodeEntities(input) {
  return String(input == null ? '' : input)
    .replace(/&([a-z]+);/gi, (whole, name) => {
      const lower = name.toLowerCase();
      if (Object.prototype.hasOwnProperty.call(NAMED_ENTITIES, lower)) {
        // &Eacute; (capitale) doit rendre É, pas é.
        const ch = NAMED_ENTITIES[lower];
        return name[0] === name[0].toUpperCase() ? ch.toUpperCase() : ch;
      }
      return whole;
    })
    .replace(/&#(\d+);/g, (_, d) => {
      const code = Number(d);
      return code > 0 && code <= 0x10ffff ? String.fromCodePoint(code) : ' ';
    })
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => {
      const code = parseInt(h, 16);
      return code > 0 && code <= 0x10ffff ? String.fromCodePoint(code) : ' ';
    })
    .replace(/&nbsp;/gi, ' ')
    .replace(/&quot;/gi, '"')
    .replace(/&apos;|&#039;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&amp;/gi, '&');
}

function stripTags(input) {
  return String(input == null ? '' : input)
    .replace(/<(?:br|\/p|\/div|\/li)[^>]*>/gi, '\n')
    .replace(/<[^>]*>/g, ' ');
}

// Chiffres arabo-indiens (٠-٩) et persans (۰-۹) vers 0-9.
function normalizeDigits(input) {
  return String(input).replace(/[٠-٩۰-۹]/g, (ch) => {
    const code = ch.charCodeAt(0);
    const base = code >= 0x06f0 ? 0x06f0 : 0x0660;
    return String(code - base);
  });
}

// Texte brut lisible : entites decodees, balises retirees, chiffres unifies.
function toPlainText(input) {
  return normalizeDigits(decodeEntities(stripTags(decodeEntities(input))))
    .replace(/[ ​-‏‪-‮⁠﻿]/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .trim();
}

// Variante latine : minuscules, sans accents, apostrophes et tirets remplaces
// par des espaces, repetitions de 3 lettres identiques ramenees a une seule.
function toLatinForm(text) {
  return String(text)
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/['‘’ʼ`_\-*.]+/g, ' ')
    .replace(/(.)\1{2,}/g, '$1')
    .replace(/\s+/g, ' ')
    .trim();
}

// Variante "leet" pour le francais : 0->o, 1->i, 4->a, 5->s, 8->b, @->a, $->s.
// Les chiffres 3, 7 et 9 sont volontairement conserves : ils codent des lettres
// arabes en darija (3=ع, 7=ح, 9=ق) et sont traites par la forme darija.
function toLeetForm(latinText) {
  return String(latinText)
    .replace(/[@]/g, 'a')
    .replace(/[$]/g, 's')
    .replace(/0/g, 'o')
    .replace(/1/g, 'i')
    .replace(/4/g, 'a')
    .replace(/5/g, 's')
    .replace(/8/g, 'b');
}

// Variante arabe : diacritiques et tatweel retires, lettres unifiees.
function toArabicForm(text) {
  return String(text)
    .replace(new RegExp('[\\u064B-\\u065F\\u0670\\u06D6-\\u06ED]', 'g'), '')
    .replace(/ـ/g, '')
    .replace(/[آأإاٱ]/g, 'ا')
    .replace(/ى/g, 'ي')
    .replace(/ة/g, 'ه')
    .replace(/ؤ/g, 'و')
    .replace(/ئ/g, 'ي')
    .replace(/\s+/g, ' ')
    .trim();
}

function escapeRegExp(term) {
  return String(term).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/* -------------------------------------------------------------------------- */
/* Recherche par mots                                                          */
/* -------------------------------------------------------------------------- */

// Frontiere de mot valable pour l'alphabet latin ET arabe : \b ne fonctionne
// pas sur l'arabe (les lettres arabes ne sont pas des caracteres \w).
const BOUNDARY_BEFORE = '(?<![\\p{L}\\p{N}_])';
const BOUNDARY_AFTER = '(?![\\p{L}\\p{N}_])';

// Prefixes (ال، و، ب، ل...) et suffixes (ه، ها، هم، ك...) courants en arabe.
const AR_PREFIX = '(?:و|ف|ب|ك|ل|ال|وال|فال|بال|كال|لل)?';
const AR_SUFFIX = '(?:ه|ها|هم|هن|ك|كم|ي|يه|ين)?';

function latinMatcher(term) {
  return new RegExp(BOUNDARY_BEFORE + escapeRegExp(term).replace(/\s+/g, '\\s+') + BOUNDARY_AFTER, 'iu');
}

function arabicMatcher(term) {
  return new RegExp(
    BOUNDARY_BEFORE + AR_PREFIX + escapeRegExp(term).replace(/\s+/g, '\\s+') + AR_SUFFIX + BOUNDARY_AFTER,
    'u',
  );
}

function findTerms(text, terms, buildMatcher) {
  const hits = [];
  for (const term of terms) {
    if (buildMatcher(term).test(text)) hits.push(term);
  }
  return hits;
}

