// TLD sans ambiguite : un domaine nu suffit a declencher la regle.
const TLD_STRONG = [
  'com', 'net', 'org', 'info', 'biz', 'xyz', 'online', 'shop', 'store', 'site',
  'club', 'top', 'vip', 'icu', 'live', 'app', 'blog', 'tech', 'pro', 'fun',
  'space', 'website', 'link', 'click', 'win', 'bid', 'agency', 'services',
];

// TLD ambigus (2 lettres surtout) : « je suis motive.ma candidature » ne doit
// pas etre pris pour un lien. On exige un schema, un www. ou un chemin.
const TLD_WEAK = [
  'ma', 'fr', 'es', 'it', 'de', 'uk', 'us', 'be', 'ch', 'ca', 'io', 'co', 'me',
  'ly', 'to', 'cc', 'tv', 'gl', 'pw', 'tk', 'cf', 'ga', 'gq', 'ru', 'eu', 'nl',
];

function detectLinks(plainText, ownDomains) {
  const hits = [];
  const seen = new Set();
  const owned = ownDomains.map((d) => d.toLowerCase().replace(/^www\./, ''));

  const isOwned = (host) => {
    const bare = host.toLowerCase().replace(/^www\./, '');
    return owned.some((d) => bare === d || bare.endsWith('.' + d));
  };

  const push = (value, host) => {
    if (isOwned(host)) return;
    const key = value.toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    hits.push(value);
  };

  // 1. URLs explicites (schema ou www.).
  const explicit = /(?:https?:\/\/|www\.)[^\s<>"')\]]+/gi;
  let m;
  while ((m = explicit.exec(plainText)) !== null) {
    const value = m[0];
    const host = value.replace(/^https?:\/\//i, '').split(/[/?#]/)[0];
    push(value, host);
  }

  // 2. Domaines nus. La casse d'origine est exigee en minuscules pour eviter
  //    les faux positifs du type « interesse.Ma formation ».
  const bare = new RegExp(
    '(?<![\\w@./-])((?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\\.)+(' +
      TLD_STRONG.concat(TLD_WEAK).join('|') +
      '))(\\/[^\\s<>"\')\\]]*)?(?![\\w-])',
    'g',
  );
  while ((m = bare.exec(plainText)) !== null) {
    const [value, host, tld, path] = m;
    if (TLD_WEAK.indexOf(tld) !== -1 && !path) continue; // trop ambigu sans chemin
    push(value, host);
  }

  return hits;
}

function detectPhones(plainText) {
  const hits = [];
  const seen = new Set();

  const candidates = /(?:\+|00)?\d[\d\s.\-()\/]{7,}\d/g;
  let m;
  while ((m = candidates.exec(plainText)) !== null) {
    const digits = m[0].replace(/\D/g, '');
    if (digits.length < 9 || digits.length > 15) continue;
    const value = m[0].trim();
    if (seen.has(value)) continue;
    seen.add(value);
    hits.push(value);
  }

  // Format marocain colle ou espace : 06xxxxxxxx, +212 6xx..., 00212...
  const moroccan = /(?:\+212|00212|0)\s*[.\-\/]?\s*[5-7](?:\s*[.\-\/]?\s*\d){8}/g;
  while ((m = moroccan.exec(plainText)) !== null) {
    const value = m[0].trim();
    if (seen.has(value)) continue;
    seen.add(value);
    hits.push(value);
  }

  return hits;
}

// Prefixes de 2 lettres a ne pas confondre avec une CIN : « DH15000 » est un
// montant en dirhams, pas une carte d'identite.
const CIN_PREFIX_EXCLUS = ['DH'];

/**
 * Numeros de carte nationale d'identite marocaine.
 *
 * Forme canonique : 1 ou 2 lettres majuscules collees a 5-7 chiffres
 * (A123456, BE12345, JC1234567). Les majuscules sont exigees telles qu'ecrites :
 * une CIN se note toujours ainsi, et cela evite d'attraper une reference
 * quelconque ecrite en minuscules au fil d'une phrase.
 *
 * Forme annoncee : un mot-cle (« CIN », « carte nationale », « رقم البطاقة »…)
 * suivi de 5 a 8 chiffres, pour les cas ou le numero est donne sans sa lettre.
 */
function detectNationalIds(plainText, latinText, arabicText) {
  const hits = [];
  const seen = new Set();

  const push = (value) => {
    const key = String(value).toUpperCase();
    if (seen.has(key)) return;
    seen.add(key);
    hits.push(value);
  };

  const canonical = /(?<![A-Za-z0-9])([A-Z]{1,2})(\d{5,7})(?![A-Za-z0-9])/g;
  let m;
  while ((m = canonical.exec(plainText)) !== null) {
    if (CIN_PREFIX_EXCLUS.indexOf(m[1]) !== -1) continue;
    push(m[0]);
  }

  const keywordLatin =
    /(?:cin|cnie|carte\s+nationale|carte\s+d\s*identite|carte\s+identite|numero\s+de\s+carte)\D{0,15}(\d{5,8})/gi;
  while ((m = keywordLatin.exec(latinText)) !== null) push(m[1]);

  const keywordArabe = /(?:البطاقه\s*الوطنيه|بطاقه\s*التعريف|رقم\s*البطاقه|بطاقتي)\D{0,15}(\d{5,8})/g;
  while ((m = keywordArabe.exec(arabicText)) !== null) push(m[1]);

  return hits;
}

function detectEmails(plainText) {
  const found = plainText.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi);
  return found ? Array.from(new Set(found)) : [];
}

