/**
 * Analyse un commentaire et renvoie la decision.
 *
 * @param {{ content?: string, authorName?: string, authorEmail?: string, authorUrl?: string }} comment
 * @param {object} [config] surcharge partielle de CONFIG
 * @returns {{ decision: 'approve'|'spam', reasons: string[], matches: object }}
 */
function classifyComment(comment, config) {
  const cfg = Object.assign({}, CONFIG, config || {});
  const rules = Object.assign({}, CONFIG.enabledRules, (config && config.enabledRules) || {});

  const plain = toPlainText(comment && comment.content);
  const authorName = toPlainText(comment && comment.authorName);
  const authorUrl = String((comment && comment.authorUrl) || '').trim();
  const authorEmail = String((comment && comment.authorEmail) || '').trim().toLowerCase();

  // Le nom d'auteur est analyse avec le contenu : le spam s'y cache souvent.
  const scanned = [plain, authorName].filter(Boolean).join('\n');

  const latin = toLatinForm(scanned);
  const leet = toLeetForm(latin);
  const arabic = toArabicForm(scanned);

  const matches = {};
  const reasons = [];

  const record = (rule, hits) => {
    if (!rules[rule] || !hits || hits.length === 0) return;
    matches[rule] = (matches[rule] || []).concat(hits);
    if (reasons.indexOf(rule) === -1) reasons.push(rule);
  };

  if (cfg.trustedAuthorEmails.indexOf(authorEmail) !== -1) {
    return { decision: 'approve', reasons: [], matches: {}, trusted: true };
  }

  record('telephone', detectPhones(plain));
  record('cin', detectNationalIds(plain, latin, arabic));
  record('email', detectEmails(scanned));

  const links = detectLinks(plain, cfg.ownDomains);
  if (authorUrl) {
    links.push.apply(links, detectLinks(authorUrl, cfg.ownDomains));
  }
  record('lien', links);

  record('pub', findTerms(latin, PROMO_TERMS_LATIN, latinMatcher));
  record('pub', findTerms(arabic, PROMO_TERMS_AR, arabicMatcher));

  record('insulte_fr', findTerms(leet, INSULTS_FR, latinMatcher));
  record('insulte_fr_legere', findTerms(leet, INSULTS_FR_MILD, latinMatcher));

  record('insulte_ar', findTerms(arabic, INSULTS_AR_SCRIPT, arabicMatcher));
  record('insulte_ar', findTerms(latin, INSULTS_AR_LATIN, latinMatcher));

  record('haine', findTerms(latin, HATE_TERMS_LATIN, latinMatcher));
  record('haine', findTerms(arabic, HATE_TERMS_AR, arabicMatcher));

  record('dementi', findTerms(latin, DOUBT_TERMS_LATIN, latinMatcher));
  record('dementi', findTerms(arabic, DOUBT_TERMS_AR, arabicMatcher));

  return {
    decision: reasons.length > 0 ? 'spam' : 'approve',
    reasons,
    matches,
  };
}

function describeReasons(reasons) {
  return reasons.map((r) => RULE_LABELS[r] || r);
}

