const results = [];

for (const item of $input.all()) {
  const c = item.json || {};
  const rawContent =
    (c.content && (c.content.raw || c.content.rendered)) ||
    (typeof c.content === 'string' ? c.content : '') ||
    '';

  const verdict = classifyComment({
    content: rawContent,
    authorName: c.author_name,
    authorEmail: c.author_email,
    authorUrl: c.author_url,
  });

  results.push({
    json: {
      commentId: c.id,
      postId: c.post,
      postLink: c.link || '',
      authorName: c.author_name || '(anonyme)',
      authorEmail: c.author_email || '',
      authorUrl: c.author_url || '',
      date: c.date || '',
      excerpt: toPlainText(rawContent).slice(0, 400),
      decision: verdict.decision,
      // En mode simulation aucune action n'est envoyee a WordPress.
      action: CONFIG.dryRun ? 'skip' : verdict.decision,
      dryRun: CONFIG.dryRun,
      reasons: verdict.reasons,
      reasonLabels: describeReasons(verdict.reasons),
      matches: verdict.matches,
    },
  });
}

return results;

/* ========================================================================== */
/* Noeud « Construire le rapport »                                             */
/* Produit le corps HTML + la charge utile Elastic Email.                      */
/* ========================================================================== */

const REPORT_TO = 'contact@dreamjob.ma';
const REPORT_FROM = 'contact@dreamjob.ma';
const ADMIN_URL = 'https://www.dreamjob.ma/wp-admin/edit-comments.php';

// Plafond : un seul e-mail par 24 h, quel que soit le nombre d'executions.
// Le seuil est fixe a 23 h et non 24 h : le declencheur quotidien peut demarrer
// quelques secondes plus tot que la veille, et un seuil de 24 h pile ferait
// silencieusement sauter un rapport sur deux.
const MIN_INTERVAL_MS = 23 * 60 * 60 * 1000;

const staticData = $getWorkflowStaticData('global');
const lastSentAt = Number(staticData.lastReportSentAt || 0);
const nowMs = Date.now();

if (lastSentAt && nowMs - lastSentAt < MIN_INTERVAL_MS) {
  // Renvoyer 0 item stoppe la chaine : le noeud d'envoi ne s'execute pas.
  // La moderation, elle, a deja eu lieu en amont.
  return [];
}

const rows = $('Appliquer les règles')
  .all()
  .map((i) => i.json);

const rejected = rows.filter((r) => r.decision === 'spam');
const approved = rows.filter((r) => r.decision === 'approve');
const dryRun = rows.length > 0 ? Boolean(rows[0].dryRun) : false;

const now = new Date();
const dateLabel = now.toLocaleDateString('fr-FR', {
  weekday: 'long',
  day: 'numeric',
  month: 'long',
  year: 'numeric',
  timeZone: 'Africa/Casablanca',
});

function esc(value) {
  return String(value == null ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function shorten(value, max) {
  const s = String(value == null ? '' : value);
  return s.length > max ? s.slice(0, max) + '…' : s;
}

function matchDetails(matches) {
  const parts = [];
  for (const key of Object.keys(matches || {})) {
    const values = (matches[key] || []).slice(0, 4).map((v) => shorten(v, 40));
    parts.push(esc(values.join(', ')));
  }
  return parts.join(' | ');
}

function table(list, withReasons) {
  if (list.length === 0) {
    return '<p style="color:#777;margin:8px 0 20px">Aucun.</p>';
  }
  const head =
    '<tr style="background:#f4f5f7;text-align:left">' +
    '<th style="padding:8px;border:1px solid #ddd">#</th>' +
    '<th style="padding:8px;border:1px solid #ddd">Auteur</th>' +
    '<th style="padding:8px;border:1px solid #ddd">Commentaire</th>' +
    (withReasons ? '<th style="padding:8px;border:1px solid #ddd">Motif</th>' : '') +
    '</tr>';

  const body = list
    .map((r) => {
      const link = r.postLink
        ? '<a href="' + esc(r.postLink) + '">' + esc(r.commentId) + '</a>'
        : esc(r.commentId);
      const reasons = withReasons
        ? '<td style="padding:8px;border:1px solid #ddd;vertical-align:top">' +
          '<strong>' + esc((r.reasonLabels || []).join(', ')) + '</strong>' +
          '<div style="color:#888;font-size:12px;margin-top:4px">' + matchDetails(r.matches) + '</div>' +
          '</td>'
        : '';
      return (
        '<tr>' +
        '<td style="padding:8px;border:1px solid #ddd;vertical-align:top">' + link + '</td>' +
        '<td style="padding:8px;border:1px solid #ddd;vertical-align:top">' + esc(r.authorName) + '</td>' +
        '<td style="padding:8px;border:1px solid #ddd;vertical-align:top">' + esc(shorten(r.excerpt, 220)) + '</td>' +
        reasons +
        '</tr>'
      );
    })
    .join('');

  return '<table style="border-collapse:collapse;width:100%;font-size:14px;margin-bottom:24px">' + head + body + '</table>';
}

const banner = dryRun
  ? '<p style="background:#fff4e5;border-left:4px solid #ff9800;padding:10px 14px;margin:0 0 20px">' +
    '<strong>Mode simulation actif.</strong> Aucun commentaire n’a été modifié sur le site. ' +
    'Passez <code>CONFIG.dryRun</code> à <code>false</code> dans le nœud « Appliquer les règles » pour activer les actions.' +
    '</p>'
  : '';

const html =
  '<div style="font-family:Arial,Helvetica,sans-serif;color:#222;max-width:900px">' +
  '<h2 style="margin:0 0 4px">Modération des commentaires — dreamjob.ma</h2>' +
  '<p style="color:#666;margin:0 0 20px">' + esc(dateLabel) + '</p>' +
  banner +
  '<p style="font-size:15px">' +
  '<strong>' + rows.length + '</strong> commentaire(s) en attente traité(s) — ' +
  '<span style="color:#1a7f37"><strong>' + approved.length + '</strong> approuvé(s)</span>, ' +
  '<span style="color:#b42318"><strong>' + rejected.length + '</strong> rejeté(s)</span>.' +
  '</p>' +
  '<h3 style="margin:24px 0 8px;color:#b42318">Rejetés (marqués comme spam)</h3>' +
  table(rejected, true) +
  '<h3 style="margin:24px 0 8px;color:#1a7f37">Approuvés</h3>' +
  table(approved, false) +
  '<p style="font-size:13px;color:#666">' +
  'Vérifier ou corriger dans WordPress : <a href="' + ADMIN_URL + '">' + ADMIN_URL + '</a>' +
  '</p>' +
  '</div>';

const subject =
  'DreamJob — modération commentaires : ' +
  approved.length + ' approuvé(s), ' + rejected.length + ' rejeté(s)' +
  (dryRun ? ' [simulation]' : '');

staticData.lastReportSentAt = nowMs;

return [
  {
    json: {
      total: rows.length,
      approvedCount: approved.length,
      rejectedCount: rejected.length,
      dryRun,
      emailPayload: {
        Recipients: [{ Email: REPORT_TO }],
        Content: {
          From: REPORT_FROM,
          Subject: subject,
          Body: [{ ContentType: 'HTML', Charset: 'utf-8', Content: html }],
        },
      },
    },
  },
];

